{
  "name": "neon-3v3",
  "private": true,
  "version": "0.1.0",
  "type": "module",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3002",
    "build": "vite build --base ./",
    "preview": "vite preview --host 0.0.0.0 --port 3002"
  },
  "dependencies": {
    "three": "^0.187.0"
  },
  "devDependencies": {
    "vite": "^8.3.7"
  }
}

@font-face {
  font-family: 'Bebas Neue';
  src: url('./assets/fonts/BebasNeue-Regular.ttf') format('truetype');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Manrope';
  src: url('./assets/fonts/Manrope-Regular.ttf') format('truetype');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Manrope';
  src: url('./assets/fonts/Manrope-SemiBold.ttf') format('truetype');
  font-weight: 600;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Manrope';
  src: url('./assets/fonts/Manrope-Bold.ttf') format('truetype');
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Manrope';
  src: url('./assets/fonts/Manrope-ExtraBold.ttf') format('truetype');
  font-weight: 800;
  font-style: normal;
  font-display: swap;
}

:root {
  --bg: #05080f;
  --bg-2: #081120;
  --panel: rgba(10, 18, 31, 0.74);
  --panel-solid: #0b1422;
  --line: rgba(157, 190, 232, 0.16);
  --line-strong: rgba(180, 214, 255, 0.3);
  --text: #edf4ff;
  --muted: #8fa2c0;
  --lime: #d7ff4a;
  --lime-soft: rgba(215, 255, 74, 0.14);
  --cyan: #44f3ff;
  --cyan-soft: rgba(68, 243, 255, 0.14);
  --magenta: #ff4b9d;
  --orange: #ffb44a;
  --danger: #ff5c5c;
  --display: 'Bebas Neue', 'Arial Narrow', Impact, sans-serif;
  --body: 'Manrope', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: var(--body);
  overflow: hidden;
  overscroll-behavior: none;
}

body {
  position: fixed;
  inset: 0;
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-font-smoothing: antialiased;
}

#app { position: fixed; inset: 0; overflow: hidden; }

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  touch-action: none;
}

.scene-shade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 46%, transparent 38%, rgba(0, 3, 10, 0.42) 100%),
    linear-gradient(180deg, rgba(2, 5, 12, 0.52) 0%, transparent 22%, transparent 68%, rgba(2, 5, 12, 0.66) 100%);
  z-index: 2;
}

.grain {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  opacity: 0.055;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  mix-blend-mode: overlay;
}

button { font-family: inherit; color: inherit; border: 0; background: none; cursor: pointer; }
button:focus-visible { outline: 2px solid var(--lime); outline-offset: 3px; }

.is-hidden { display: none !important; }

/* ============================== HUD ============================== */
.hud {
  position: absolute;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  opacity: 1;
  transition: opacity 0.35s var(--ease);
}

.hud-top {
  position: absolute;
  top: calc(10px + var(--safe-t));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  justify-content: center;
  width: min(560px, calc(100% - 24px));
}

.scorebug {
  position: relative;
  display: flex;
  align-items: center;
  gap: clamp(8px, 1.4vw, 18px);
  min-width: min(360px, 100%);
  padding: 7px clamp(14px, 2.2vw, 24px) 6px;
  background: linear-gradient(180deg, rgba(13, 23, 39, 0.92), rgba(6, 12, 22, 0.86));
  border: 1px solid var(--line-strong);
  border-radius: 14px;
  box-shadow: 0 14px 38px rgba(0, 0, 0, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(14px);
}

.scorebug::before {
  content: '';
  position: absolute;
  inset: auto 18% -1px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--lime), transparent);
  opacity: 0.7;
}

.team { display: flex; align-items: center; gap: 8px; flex: 1; }
.team-away { justify-content: flex-end; }
.team-mark {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 7px;
  font-family: var(--display);
  font-size: 17px;
  letter-spacing: 0.04em;
  color: #041018;
  background: linear-gradient(140deg, var(--cyan), #b7feff);
  box-shadow: 0 0 18px rgba(68, 243, 255, 0.4);
}
.team-away .team-mark {
  color: #190612;
  background: linear-gradient(140deg, var(--magenta), #ff9ec8);
  box-shadow: 0 0 18px rgba(255, 75, 157, 0.4);
}
.team-name {
  font-family: var(--display);
  font-size: 20px;
  letter-spacing: 0.09em;
  line-height: 1;
}
.team-home .team-name { color: #d6feff; }
.team-away .team-name { color: #ffd7e7; }

.score-wrap {
  display: flex;
  align-items: baseline;
  gap: 3px;
  font-family: var(--display);
  line-height: 0.9;
}
.score-num { font-size: clamp(28px, 4.6vw, 42px); font-variant-numeric: tabular-nums; letter-spacing: 0.02em; }
.score-sep { font-size: 26px; color: var(--muted); opacity: 0.6; transform: translateY(-2px); }

.clock-wrap {
  position: absolute;
  left: 50%;
  bottom: -20px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 3px 12px;
  background: rgba(5, 10, 18, 0.92);
  border: 1px solid var(--line);
  border-radius: 999px;
  white-space: nowrap;
}
.clock {
  font-family: var(--display);
  font-size: 16px;
  letter-spacing: 0.09em;
  color: var(--lime);
  font-variant-numeric: tabular-nums;
}
.clock-label {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.16em;
  color: var(--muted);
}
.clock-wrap.is-golden .clock { color: var(--magenta); }
.clock-wrap.is-golden .clock-label { color: var(--magenta); }

.icon-btn {
  pointer-events: auto;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: rgba(9, 16, 28, 0.72);
  display: grid;
  place-items: center;
  color: var(--text);
  backdrop-filter: blur(12px);
  transition: background 0.18s, border-color 0.18s, transform 0.18s;
}
.icon-btn:hover { background: rgba(24, 38, 60, 0.9); border-color: var(--line-strong); }
.icon-btn:active { transform: scale(0.94); }
.icon-btn svg { width: 19px; height: 19px; fill: currentColor; }

#pauseBtn {
  position: absolute;
  right: calc(12px + var(--safe-r));
  top: 0;
}

.hud-side {
  position: absolute;
  right: calc(16px + var(--safe-r));
  top: calc(84px + var(--safe-t));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
}

.style-chip {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px 11px;
  border: 1px solid rgba(215, 255, 74, 0.35);
  border-radius: 999px;
  background: rgba(9, 18, 20, 0.66);
  font-family: var(--display);
  font-size: 15px;
  letter-spacing: 0.12em;
  color: var(--lime);
  backdrop-filter: blur(10px);
}
.style-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 10px var(--lime);
}

.mini-stats {
  display: flex;
  gap: 7px;
}
.mini-stats div {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  padding: 5px 9px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgba(9, 16, 28, 0.6);
  backdrop-filter: blur(8px);
}
.mini-stats span { font-size: 7px; font-weight: 800; letter-spacing: 0.14em; color: var(--muted); }
.mini-stats b { font-family: var(--display); font-size: 16px; letter-spacing: 0.06em; font-weight: 400; }

.player-card {
  position: absolute;
  left: calc(18px + var(--safe-l));
  bottom: calc(18px + var(--safe-b));
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 13px 7px 7px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(7, 14, 25, 0.72);
  backdrop-filter: blur(12px);
}
.avatar {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 9px;
  background: linear-gradient(145deg, var(--cyan), #0b7382);
  color: #02131a;
  font-family: var(--display);
  font-size: 21px;
}
.player-meta { display: flex; flex-direction: column; gap: 2px; min-width: 86px; }
.player-name { font-family: var(--display); font-size: 17px; letter-spacing: 0.08em; line-height: 1; }
.player-style { font-size: 7px; letter-spacing: 0.18em; font-weight: 800; color: var(--lime); }
.stamina {
  width: 100%;
  height: 3px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.13);
  overflow: hidden;
  margin-top: 2px;
}
.stamina i {
  display: block;
  height: 100%;
  width: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--cyan), var(--lime));
  transition: width 0.12s linear;
}
.stamina.is-low i { background: linear-gradient(90deg, var(--orange), var(--danger)); }

.hint-bar {
  position: absolute;
  left: 50%;
  bottom: calc(22px + var(--safe-b));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 14px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(6, 12, 22, 0.7);
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.04em;
  backdrop-filter: blur(10px);
  transition: opacity 0.4s;
  white-space: nowrap;
}
.hint-key {
  padding: 2px 6px;
  border-radius: 4px;
  background: var(--lime);
  color: #0a1206;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.08em;
}
.hint-bar.is-faded { opacity: 0; }

.desktop-hint {
  position: absolute;
  z-index: 12;
  left: 50%;
  bottom: calc(8px + var(--safe-b));
  transform: translateX(-50%);
  display: flex;
  gap: 14px;
  font-size: 9px;
  letter-spacing: 0.05em;
  color: rgba(200, 218, 240, 0.5);
  white-space: nowrap;
  pointer-events: none;
}
.desktop-hint b { color: rgba(230, 242, 255, 0.82); font-weight: 800; }

/* ============================== TOUCH ============================== */
.touch-ui {
  position: absolute;
  inset: auto 0 0 0;
  height: 220px;
  display: none;
  pointer-events: none;
}

.stick-wrap {
  position: absolute;
  left: calc(16px + var(--safe-l));
  bottom: calc(14px + var(--safe-b));
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  pointer-events: auto;
}
.stick-base {
  position: relative;
  width: clamp(104px, 26vw, 140px);
  height: clamp(104px, 26vw, 140px);
  border-radius: 50%;
  border: 1px solid rgba(157, 190, 232, 0.22);
  background: radial-gradient(circle at 50% 45%, rgba(28, 48, 76, 0.46), rgba(6, 12, 22, 0.56));
  box-shadow: inset 0 0 28px rgba(0, 0, 0, 0.32), 0 10px 28px rgba(0, 0, 0, 0.24);
  backdrop-filter: blur(7px);
  touch-action: none;
}
.stick-ring {
  position: absolute;
  inset: 18%;
  border-radius: 50%;
  border: 1px dashed rgba(157, 190, 232, 0.2);
}
.stick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 42%;
  height: 42%;
  margin: -21% 0 0 -21%;
  border-radius: 50%;
  background: radial-gradient(circle at 36% 30%, rgba(68, 243, 255, 0.95), rgba(23, 156, 172, 0.9) 48%, rgba(8, 60, 71, 0.94));
  border: 1px solid rgba(190, 252, 255, 0.65);
  box-shadow: 0 0 18px rgba(68, 243, 255, 0.34), inset 0 2px 8px rgba(255, 255, 255, 0.3);
  transition: transform 0.05s linear;
  will-change: transform;
}
.stick-knob span {
  position: absolute;
  inset: 34%;
  border-radius: 50%;
  border: 1px solid rgba(4, 25, 30, 0.38);
}
.stick-label {
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.24em;
  color: rgba(185, 205, 230, 0.5);
}

.action-cluster {
  position: absolute;
  right: calc(14px + var(--safe-r));
  bottom: calc(12px + var(--safe-b));
  display: grid;
  grid-template-columns: 1fr 1.18fr;
  grid-template-areas:
    'pass skill'
    'sprint shoot';
  gap: 8px;
  align-items: end;
  justify-items: end;
  pointer-events: auto;
}

.tbtn {
  position: relative;
  width: clamp(54px, 14vw, 68px);
  height: clamp(54px, 14vw, 68px);
  border-radius: 50%;
  border: 1px solid rgba(157, 190, 232, 0.28);
  background: radial-gradient(circle at 38% 30%, rgba(35, 56, 86, 0.82), rgba(8, 15, 27, 0.9));
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.32), inset 0 1px 0 rgba(255, 255, 255, 0.12);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  backdrop-filter: blur(8px);
  touch-action: none;
  transition: transform 0.08s ease, background 0.15s, border-color 0.15s;
}
.tbtn:active, .tbtn.is-down { transform: scale(0.92); background: radial-gradient(circle at 38% 30%, rgba(60, 88, 128, 0.9), rgba(14, 26, 44, 0.95)); }
.tbtn-label { font-family: var(--display); font-size: clamp(14px, 3.6vw, 17px); letter-spacing: 0.08em; line-height: 1; }
.tbtn-key { font-size: 6px; font-weight: 800; letter-spacing: 0.12em; color: rgba(180, 202, 228, 0.5); }
.tbtn-pass { grid-area: pass; }
.tbtn-skill { grid-area: skill; border-color: rgba(255, 75, 157, 0.3); }
.tbtn-skill .tbtn-label { color: #ffd3e5; }
.tbtn-sprint { grid-area: sprint; }
.tbtn-sprint .tbtn-label { color: #c9fbff; }
.tbtn-shoot {
  grid-area: shoot;
  width: clamp(74px, 19vw, 96px);
  height: clamp(74px, 19vw, 96px);
  border: 1px solid rgba(215, 255, 74, 0.5);
  background: radial-gradient(circle at 36% 28%, rgba(215, 255, 74, 0.26), rgba(19, 35, 20, 0.9) 62%);
  box-shadow: 0 0 26px rgba(215, 255, 74, 0.14), 0 10px 24px rgba(0, 0, 0, 0.34), inset 0 1px 0 rgba(255, 255, 255, 0.14);
}
.tbtn-shoot .tbtn-label {
  font-size: clamp(19px, 4.8vw, 24px);
  color: var(--lime);
  text-shadow: 0 0 14px rgba(215, 255, 74, 0.34);
}
.tbtn-shoot .tbtn-key { color: rgba(215, 255, 74, 0.52); }
.tbtn-shoot::before {
  content: '';
  position: absolute;
  inset: -5px;
  border-radius: 50%;
  background: conic-gradient(from -90deg, var(--lime) calc(var(--power, 0) * 1turn), rgba(255, 255, 255, 0.11) 0);
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 2px));
  mask: radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 2px));
  opacity: 0;
  transition: opacity 0.12s;
}
.tbtn-shoot.is-charging::before { opacity: 1; }
.tbtn-shoot.is-perfect { box-shadow: 0 0 36px rgba(215, 255, 74, 0.55), inset 0 0 20px rgba(215, 255, 74, 0.18); }
.tbtn-glow {
  position: absolute;
  inset: -2px;
  border-radius: 50%;
  box-shadow: 0 0 0 rgba(215, 255, 74, 0);
  transition: box-shadow 0.15s;
}
.tbtn-shoot.is-charging .tbtn-glow { box-shadow: 0 0 32px rgba(215, 255, 74, 0.24); }

/* ============================== TOAST / GOAL ============================== */
.toast {
  position: absolute;
  z-index: 15;
  left: 50%;
  top: 24%;
  transform: translate(-50%, -14px) scale(0.94);
  padding: 9px 22px;
  border: 1px solid rgba(215, 255, 74, 0.35);
  border-radius: 999px;
  background: rgba(6, 13, 22, 0.82);
  font-family: var(--display);
  font-size: clamp(18px, 3.4vw, 28px);
  letter-spacing: 0.14em;
  color: var(--lime);
  text-align: center;
  opacity: 0;
  pointer-events: none;
  backdrop-filter: blur(12px);
  transition: opacity 0.2s, transform 0.35s var(--ease);
  white-space: nowrap;
}
.toast.is-show { opacity: 1; transform: translate(-50%, 0) scale(1); }
.toast.is-bad { color: #ffcf5c; border-color: rgba(255, 207, 92, 0.4); }
.toast.is-danger { color: #ff7a9c; border-color: rgba(255, 122, 156, 0.4); }

.goal-flash {
  position: absolute;
  inset: 0;
  z-index: 14;
  display: grid;
  place-items: center;
  pointer-events: none;
  background: radial-gradient(ellipse at 50% 46%, rgba(14, 40, 20, 0.25), rgba(2, 4, 9, 0.66) 78%);
  animation: goalFlashIn 0.35s var(--ease) both;
}
.goal-flash::before,
.goal-flash::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(215, 255, 74, 0.75), transparent);
}
.goal-flash::before { top: 37%; }
.goal-flash::after { bottom: 37%; }
.goal-inner { text-align: center; transform: rotate(-2deg); animation: goalPop 0.55s var(--ease) both; }
.goal-kicker {
  display: block;
  font-size: clamp(10px, 1.4vw, 13px);
  font-weight: 800;
  letter-spacing: 0.42em;
  color: var(--cyan);
  margin-bottom: 2px;
}
.goal-word {
  display: block;
  font-family: var(--display);
  font-size: clamp(96px, 20vw, 240px);
  line-height: 0.78;
  letter-spacing: 0.02em;
  color: var(--lime);
  text-shadow: 0 0 60px rgba(215, 255, 74, 0.35), 0 0 2px #fff;
}
.goal-scorer {
  display: inline-block;
  margin-top: 12px;
  padding: 5px 18px;
  border: 1px solid rgba(215, 255, 74, 0.4);
  border-radius: 999px;
  background: rgba(6, 12, 10, 0.7);
  font-family: var(--display);
  font-size: clamp(20px, 3vw, 30px);
  letter-spacing: 0.22em;
  color: #f3ffd0;
}
@keyframes goalFlashIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes goalPop {
  0% { transform: rotate(-2deg) scale(0.72); opacity: 0; }
  60% { transform: rotate(-2deg) scale(1.04); opacity: 1; }
  100% { transform: rotate(-2deg) scale(1); opacity: 1; }
}

.flash {
  position: absolute;
  inset: 0;
  z-index: 20;
  pointer-events: none;
  background: #f4ffd8;
  opacity: 0;
}
.flash.is-on { animation: flashPop 0.45s ease-out both; }
@keyframes flashPop { 0% { opacity: 0.5; } 100% { opacity: 0; } }

/* ============================== SCREENS ============================== */
.screen {
  position: absolute;
  inset: 0;
  z-index: 30;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
}

.menu {
  display: flex;
  flex-direction: column;
  padding: calc(20px + var(--safe-t)) clamp(18px, 4.4vw, 68px) 18px;
  background:
    linear-gradient(90deg, rgba(3, 7, 15, 0.94) 0%, rgba(3, 7, 15, 0.58) 42%, rgba(3, 7, 15, 0.74) 100%),
    radial-gradient(ellipse at 68% 24%, rgba(68, 243, 255, 0.1), transparent 48%),
    radial-gradient(ellipse at 10% 88%, rgba(215, 255, 74, 0.08), transparent 46%);
  backdrop-filter: blur(2px);
}

/* faint pitch markings behind the menu */
.menu::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(90deg, transparent 49.9%, rgba(157, 190, 232, 0.06) 50%, transparent 50.1%),
    radial-gradient(circle at 50% 50%, transparent 17.9%, rgba(157, 190, 232, 0.07) 18%, transparent 18.3%);
  background-size: 100% 100%, 460px 460px;
  background-position: center, center;
  opacity: 0.7;
}

.menu-top {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-shrink: 0;
}
.brand { display: flex; align-items: center; gap: 11px; }
.brand-mark {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 10px;
  border: 1px solid rgba(215, 255, 74, 0.42);
  background: linear-gradient(150deg, rgba(215, 255, 74, 0.18), rgba(6, 12, 8, 0.7));
  font-family: var(--display);
  font-size: 25px;
  line-height: 1;
  color: var(--lime);
  letter-spacing: 0.02em;
}
.brand-mark span { color: var(--cyan); }
.brand-copy { display: flex; flex-direction: column; gap: 1px; }
.brand-copy b { font-family: var(--display); font-size: 18px; letter-spacing: 0.16em; line-height: 1; }
.brand-copy span { font-size: 7px; font-weight: 800; letter-spacing: 0.2em; color: var(--muted); }
.top-actions { display: flex; align-items: center; gap: 9px; }
.sound-btn .icon-off { display: none; }
.sound-btn.is-muted .icon-on { display: none; }
.sound-btn.is-muted .icon-off { display: block; }
.sound-btn svg { stroke: currentColor; }
.sound-btn svg path:first-child { stroke: none; fill: currentColor; }

.menu-grid {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: 1380px;
  margin: auto;
  display: grid;
  grid-template-columns: minmax(0, 1.02fr) minmax(430px, 0.98fr);
  align-items: center;
  gap: clamp(24px, 4.6vw, 74px);
  padding: clamp(18px, 3.4vh, 40px) 0;
}

.hero { min-width: 0; }
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 11px;
  border: 1px solid rgba(68, 243, 255, 0.28);
  border-radius: 999px;
  background: rgba(8, 20, 28, 0.6);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.2em;
  color: #b9f7ff;
}
.live-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan);
  animation: blink 1.8s infinite;
}
@keyframes blink { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }

.hero-title {
  margin: 14px 0 0;
  display: flex;
  flex-direction: column;
  font-family: var(--display);
  font-weight: 400;
  line-height: 0.77;
  letter-spacing: 0.008em;
}
.hero-neon {
  font-size: clamp(86px, 11.2vw, 164px);
  color: #f3f8ff;
  text-shadow: 0 0 50px rgba(68, 243, 255, 0.12);
}
.hero-3v3 {
  display: flex;
  align-items: baseline;
  gap: 0.03em;
  font-size: clamp(92px, 12.4vw, 186px);
  color: var(--lime);
  text-shadow: 0 0 60px rgba(215, 255, 74, 0.18);
}
.hero-3v3 span {
  color: transparent;
  -webkit-text-stroke: 2px var(--cyan);
  text-shadow: 0 0 32px rgba(68, 243, 255, 0.24);
  font-size: 0.62em;
  transform: translateY(-0.06em);
}
.hero-tag {
  margin: 16px 0 0;
  font-size: clamp(13px, 1.25vw, 17px);
  line-height: 1.55;
  font-weight: 600;
  color: #c7d5e9;
  max-width: 44ch;
}
.hero-tag em { color: #8fa2c0; font-style: normal; font-weight: 400; }
.hero-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }
.hero-chips span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 9px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: rgba(8, 15, 26, 0.45);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: #a9bdd6;
}
.hero-chips i { width: 4px; height: 4px; border-radius: 50%; background: var(--cyan); }
.hero-chips span:nth-child(2) i { background: var(--lime); }
.hero-chips span:nth-child(3) i { background: var(--magenta); }

.hero-stats {
  display: flex;
  gap: clamp(18px, 3vw, 38px);
  margin-top: 24px;
  padding-top: 16px;
  border-top: 1px solid var(--line);
  max-width: 430px;
}
.hero-stats div { display: flex; flex-direction: column; gap: 1px; }
.hero-stats b { font-family: var(--display); font-size: 27px; font-weight: 400; letter-spacing: 0.05em; line-height: 1; color: #f3f8ff; }
.hero-stats span { font-size: 7px; font-weight: 800; letter-spacing: 0.16em; color: var(--muted); }

.control-note {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 18px;
  max-width: 46ch;
}
.control-note b { font-size: 7px; font-weight: 800; letter-spacing: 0.22em; color: var(--lime); }
.control-note span { font-size: 10px; line-height: 1.6; color: #8fa2c0; }
.control-note em { font-style: normal; color: #dbe8f8; font-weight: 700; }

/* ---------- setup panel ---------- */
.setup {
  position: relative;
  border: 1px solid var(--line-strong);
  border-radius: 20px;
  background: linear-gradient(165deg, rgba(13, 23, 39, 0.88), rgba(6, 12, 22, 0.9));
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  padding: clamp(16px, 2.2vw, 26px);
  backdrop-filter: blur(18px);
}
.setup::before {
  content: '';
  position: absolute;
  top: -1px;
  left: 12%;
  right: 12%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(215, 255, 74, 0.65), transparent);
}
.setup-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; margin-bottom: 14px; }
.setup-kicker { display: block; font-size: 7px; font-weight: 800; letter-spacing: 0.24em; color: var(--lime); margin-bottom: 3px; }
.setup-head h2 {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(24px, 2.3vw, 31px);
  letter-spacing: 0.04em;
  font-weight: 400;
  line-height: 1;
}
.setup-number {
  font-family: var(--display);
  font-size: 30px;
  line-height: 1;
  color: rgba(157, 190, 232, 0.2);
}

.styles {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.style-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  text-align: left;
  gap: 1px;
  padding: 11px 11px 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(7, 14, 25, 0.62);
  overflow: hidden;
  transition: border-color 0.18s, background 0.18s, transform 0.18s;
}
.style-card:hover { border-color: rgba(68, 243, 255, 0.4); background: rgba(13, 25, 42, 0.8); transform: translateY(-1px); }
.style-card .style-icon { width: 22px; height: 22px; margin-bottom: 4px; color: rgba(157, 190, 232, 0.72); }
.style-icon svg { width: 100%; height: 100%; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.style-card .style-icon svg circle:first-child { fill: none; }
.style-name { font-family: var(--display); font-size: 21px; line-height: 1; letter-spacing: 0.07em; }
.style-desc { font-size: 8px; font-weight: 700; letter-spacing: 0.06em; color: #94a8c4; margin-top: 2px; }
.style-perk { font-size: 7px; line-height: 1.4; color: #627795; margin-top: 4px; letter-spacing: 0.02em; }
.style-check {
  display: none;
  position: absolute;
  top: 8px;
  right: 8px;
  padding: 2px 5px;
  border-radius: 3px;
  background: var(--lime);
  color: #0a1206;
  font-size: 5.5px;
  font-weight: 800;
  letter-spacing: 0.1em;
}
.style-card.is-selected {
  border-color: rgba(215, 255, 74, 0.62);
  background: linear-gradient(155deg, rgba(215, 255, 74, 0.12), rgba(8, 16, 24, 0.82) 58%);
  box-shadow: inset 0 0 24px rgba(215, 255, 74, 0.05);
}
.style-card.is-selected .style-icon { color: var(--lime); }
.style-card.is-selected .style-check { display: block; }
.style-card.is-selected .style-name { color: #f4ffd2; }
.style-card[data-style='sniper'] .style-icon { color: #ff9cc4; }
.style-card[data-style='engine'] .style-icon { color: #7ff8ff; }
.style-card[data-style='anchor'] .style-icon { color: #ffc879; }
.style-card.is-selected[data-style='sniper'] { border-color: rgba(255, 75, 157, 0.6); background: linear-gradient(155deg, rgba(255, 75, 157, 0.12), rgba(8, 16, 24, 0.82) 58%); }
.style-card.is-selected[data-style='sniper'] .style-check { background: var(--magenta); color: #fff; }
.style-card.is-selected[data-style='engine'] { border-color: rgba(68, 243, 255, 0.6); background: linear-gradient(155deg, rgba(68, 243, 255, 0.12), rgba(8, 16, 24, 0.82) 58%); }
.style-card.is-selected[data-style='engine'] .style-check { background: var(--cyan); color: #04141a; }
.style-card.is-selected[data-style='anchor'] { border-color: rgba(255, 180, 74, 0.6); background: linear-gradient(155deg, rgba(255, 180, 74, 0.12), rgba(8, 16, 24, 0.82) 58%); }
.style-card.is-selected[data-style='anchor'] .style-check { background: var(--orange); color: #1c0f02; }
.style-card.is-selected[data-style='sniper'] .style-name { color: #ffd7e7; }
.style-card.is-selected[data-style='engine'] .style-name { color: #d4feff; }
.style-card.is-selected[data-style='anchor'] .style-name { color: #ffedcf; }

.setup-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  margin-top: 14px;
}
.setup-block { display: flex; flex-direction: column; gap: 5px; min-width: 0; }
.setup-label { font-size: 6.5px; font-weight: 800; letter-spacing: 0.2em; color: var(--muted); }
.segmented {
  display: flex;
  gap: 2px;
  padding: 3px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(4, 9, 16, 0.6);
}
.segmented button {
  padding: 6px 9px;
  border-radius: 5px;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: #8397b3;
  transition: background 0.15s, color 0.15s;
}
.segmented button:hover { color: #dce9fa; }
.segmented button.is-on { background: var(--lime); color: #0b1305; }

.play-btn {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 22px 10px 12px;
  border-radius: 12px;
  background: linear-gradient(135deg, var(--lime), #b6ef2f);
  color: #0a1304;
  box-shadow: 0 10px 30px rgba(180, 240, 47, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.45);
  overflow: hidden;
  transition: transform 0.16s var(--ease), box-shadow 0.16s;
}
.play-btn::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(100deg, transparent 30%, rgba(255, 255, 255, 0.42) 50%, transparent 70%);
  transform: translateX(-120%);
  animation: playShine 4.5s 1.4s infinite;
}
@keyframes playShine { 0%, 72% { transform: translateX(-120%); } 88%, 100% { transform: translateX(120%); } }
.play-btn:hover { transform: translateY(-2px); box-shadow: 0 14px 36px rgba(180, 240, 47, 0.32), inset 0 1px 0 rgba(255, 255, 255, 0.45); }
.play-btn:active { transform: scale(0.97); }
.play-icon {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: rgba(8, 20, 4, 0.14);
}
.play-icon svg { width: 15px; height: 15px; fill: #0a1304; }
.play-copy { display: flex; flex-direction: column; align-items: flex-start; gap: 0; position: relative; z-index: 1; }
.play-copy b { font-family: var(--display); font-size: 30px; font-weight: 400; line-height: 0.92; letter-spacing: 0.04em; }
.play-copy small { font-size: 6px; font-weight: 800; letter-spacing: 0.16em; opacity: 0.62; }

.fineprint {
  margin: 11px 0 0;
  font-size: 7.5px;
  line-height: 1.5;
  letter-spacing: 0.03em;
  color: #586c88;
}

.menu-foot {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding-top: 12px;
  border-top: 1px solid rgba(157, 190, 232, 0.1);
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: #40526a;
  flex-shrink: 0;
}

/* ============================== MODALS ============================== */
.pause, .end {
  display: grid;
  place-items: center;
  padding: 20px;
  background: radial-gradient(ellipse at 50% 42%, rgba(9, 20, 34, 0.62), rgba(2, 5, 11, 0.9));
  backdrop-filter: blur(10px);
  z-index: 40;
}
.modal {
  position: relative;
  width: min(440px, 94vw);
  padding: clamp(22px, 4vw, 36px);
  border: 1px solid var(--line-strong);
  border-radius: 20px;
  background: linear-gradient(165deg, rgba(14, 26, 44, 0.96), rgba(5, 10, 18, 0.98));
