import * as THREE from 'three';
import { FIELD, TEAMS } from './constants.js';

const TAU = Math.PI * 2;

function canvasTexture(w, h, draw, opts = {}) {
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d');
  draw(ctx, w, h);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = opts.anisotropy ?? 4;
  if (opts.repeat) {
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(opts.repeat[0], opts.repeat[1]);
  }
  return tex;
}

function grassTexture() {
  return canvasTexture(
    1024,
    1024,
    (ctx, w, h) => {
      const bands = 16;
      for (let i = 0; i < bands; i++) {
        const t = i / bands;
        ctx.fillStyle = i % 2 === 0 ? '#0c3a27' : '#082f1f';
        ctx.fillRect(0, (h / bands) * i, w, h / bands + 1);
      }
      const grad = ctx.createRadialGradient(w / 2, h / 2, 80, w / 2, h / 2, w * 0.72);
      grad.addColorStop(0, 'rgba(35, 90, 56, 0.22)');
      grad.addColorStop(1, 'rgba(0, 5, 8, 0.34)');
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, w, h);

      // grass grain
      for (let i = 0; i < 16000; i++) {
        const x = Math.random() * w;
        const y = Math.random() * h;
        const a = Math.random();
        ctx.fillStyle = a > 0.5 ? `rgba(95, 170, 96, ${0.03 + Math.random() * 0.08})` : `rgba(0, 18, 9, ${0.04 + Math.random() * 0.14})`;
        ctx.fillRect(x, y, 1 + Math.random() * 2.4, 1 + Math.random() * 2);
      }
      // mow sheen
      ctx.globalAlpha = 0.06;
      ctx.fillStyle = '#b7ff8a';
      for (let i = 0; i < bands; i += 2) ctx.fillRect(0, (h / bands) * i, w, 2);
      ctx.globalAlpha = 1;
    },
    { anisotropy: 8 }
  );
}

function adTexture(lines, accent) {
  return canvasTexture(1024, 128, (ctx, w, h) => {
    ctx.fillStyle = '#050a12';
    ctx.fillRect(0, 0, w, h);
    const g = ctx.createLinearGradient(0, 0, w, 0);
    g.addColorStop(0, 'rgba(8, 18, 30, 1)');
    g.addColorStop(0.5, 'rgba(14, 26, 40, 1)');
    g.addColorStop(1, 'rgba(7, 15, 26, 1)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = accent;
    ctx.globalAlpha = 0.5;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, 8);
    ctx.lineTo(w, 8);
    ctx.moveTo(0, h - 8);
    ctx.lineTo(w, h - 8);
    ctx.stroke();
    ctx.globalAlpha = 1;
    ctx.fillStyle = accent;
    ctx.font = '700 58px Manrope, Arial, sans-serif';
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'center';
    ctx.letterSpacing = '10px';
    ctx.fillText(lines, w / 2, h / 2 + 3);
  });
}

function signTexture() {
  return canvasTexture(1024, 320, (ctx, w, h) => {
    ctx.fillStyle = '#04070d';
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = 'rgba(68,243,255,0.55)';
    ctx.lineWidth = 4;
    ctx.strokeRect(12, 12, w - 24, h - 24);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowBlur = 34;
    ctx.shadowColor = '#44f3ff';
    ctx.fillStyle = '#e9ffff';
    ctx.font = '400 148px "Bebas Neue", Impact, sans-serif';
    ctx.letterSpacing = '14px';
    ctx.fillText('NEON LEAGUE', w / 2, h * 0.43);
    ctx.shadowColor = '#d7ff4a';
    ctx.fillStyle = '#d7ff4a';
    ctx.font = '800 50px Manrope, Arial, sans-serif';
    ctx.letterSpacing = '22px';
    ctx.fillText('3 V 3  STREET FOOTBALL', w / 2, h * 0.72);
  });
}

function radialGlowTexture(inner = 'rgba(255,255,255,1)', outer = 'rgba(120,220,255,0)') {
  return canvasTexture(128, 128, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    g.addColorStop(0, inner);
    g.addColorStop(0.28, 'rgba(255,255,255,0.55)');
    g.addColorStop(0.6, 'rgba(120,230,255,0.13)');
    g.addColorStop(1, outer);
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
}

function flatMat(color, opacity = 1) {
  return new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity, depthWrite: false });
}

function addLine(group, x1, z1, x2, z2, width = 0.1, opacity = 0.52, color = 0xeafcff) {
  const dx = x2 - x1;
  const dz = z2 - z1;
  const len = Math.hypot(dx, dz);
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(len, width), flatMat(color, opacity));
  mesh.rotation.x = -Math.PI / 2;
  mesh.rotation.z = -Math.atan2(dz, dx);
  mesh.position.set((x1 + x2) / 2, 0.016, (z1 + z2) / 2);
  group.add(mesh);
  return mesh;
}

function addRing(group, x, z, radius, thickness, color = 0xeafcff, opacity = 0.45, thetaStart = 0, thetaLength = TAU) {
  const mesh = new THREE.Mesh(
    new THREE.RingGeometry(radius - thickness, radius, 72, 1, thetaStart, thetaLength),
    flatMat(color, opacity)
  );
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.set(x, 0.017, z);
  group.add(mesh);
  return mesh;
}

function makeNet(z, dir, color = 0x9fd9e6) {
  const pts = [];
  const halfW = FIELD.goalWidth / 2;
  const h = FIELD.goalHeight;
  const depth = FIELD.goalDepth;
  const back = z + dir * depth;
  const step = 0.42;
  // back grid
  for (let x = -halfW; x <= halfW + 0.001; x += step) {
    pts.push(x, 0.06, back, x, h, back);
  }
  for (let y = 0.06; y <= h + 0.001; y += step) {
    pts.push(-halfW, y, back, halfW, y, back);
  }
  // side grids
  for (const sx of [-halfW, halfW]) {
    for (let y = 0.06; y <= h + 0.001; y += step) {
      pts.push(sx, y, z, sx, y, back);
    }
    for (let zz = z; zz <= back + 0.001; zz += step) {
      pts.push(sx, 0.06, zz, sx, h, zz);
    }
  }
  // top grid
  for (let x = -halfW; x <= halfW + 0.001; x += step) {
    pts.push(x, h, z, x, h, back);
  }
  for (let zz = z; zz <= back + 0.001; zz += step) {
    pts.push(-halfW, h, zz, halfW, h, zz);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
  const mat = new THREE.LineBasicMaterial({ color, transparent: true, opacity: 0.32, depthWrite: false });
  return new THREE.LineSegments(geo, mat);
}

function createGoal(team, z) {
  const group = new THREE.Group();
  const dir = Math.sign(z);
  const halfW = FIELD.goalWidth / 2;
  const h = FIELD.goalHeight;
  const frameMat = new THREE.MeshStandardMaterial({
    color: 0xf4feff,
    roughness: 0.28,
    metalness: 0.55,
    emissive: 0xbfeaff,
    emissiveIntensity: 0.18,
  });
  const postGeo = new THREE.CylinderGeometry(0.075, 0.075, h, 10);
  for (const x of [-halfW, halfW]) {
    const post = new THREE.Mesh(postGeo, frameMat);
    post.position.set(x, h / 2, z);
    post.castShadow = true;
    group.add(post);
    // rear support
    const back = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, FIELD.goalDepth + 0.08, 8), frameMat);
    back.rotation.x = Math.PI / 2;
    back.position.set(x, 0.08, z + dir * FIELD.goalDepth * 0.5);
    group.add(back);
    const support = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, h, 8), frameMat);
    support.position.set(x, h / 2, z + dir * FIELD.goalDepth);
    group.add(support);
  }
  const bar = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.075, FIELD.goalWidth + 0.18, 10), frameMat);
  bar.rotation.z = Math.PI / 2;
  bar.position.set(0, h, z);
  bar.castShadow = true;
  group.add(bar);

  const neon = new THREE.Mesh(
    new THREE.BoxGeometry(FIELD.goalWidth - 0.2, 0.035, 0.05),
    new THREE.MeshBasicMaterial({ color: team.color })
  );
  neon.position.set(0, h - 0.13, z + 0.08 * -dir);
  group.add(neon);

  group.add(makeNet(z, dir));
  return group;
}

function createFloodlight(x, z, target, glowTex) {
  const group = new THREE.Group();
  const poleMat = new THREE.MeshStandardMaterial({ color: 0x0a1420, roughness: 0.6, metalness: 0.65 });
  const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.34, 16, 8), poleMat);
  pole.position.set(x, 8, z);
  group.add(pole);
  const head = new THREE.Group();
  head.position.set(x, 16, z);
  head.lookAt(target.x, 9, target.z);
  const housing = new THREE.Mesh(new THREE.BoxGeometry(3.4, 1.25, 0.4), poleMat);
  head.add(housing);
  const lampMat = new THREE.MeshBasicMaterial({ color: 0xf4ffff });
  for (let i = 0; i < 5; i++) {
    for (let j = 0; j < 2; j++) {
      const lamp = new THREE.Mesh(new THREE.PlaneGeometry(0.46, 0.36), lampMat);
      lamp.position.set(-1.25 + i * 0.62, -0.2 + j * 0.42, 0.21);
      head.add(lamp);
    }
  }
  group.add(head);
  const glow = new THREE.Sprite(
    new THREE.SpriteMaterial({
      map: glowTex,
      color: 0xbdefff,
      transparent: true,
      opacity: 0.9,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      depthTest: false,
    })
  );
  glow.scale.set(9, 9, 1);
  glow.position.set(x, 16, z);
  group.add(glow);
  return group;
}

function createSky(scene) {
  const geo = new THREE.SphereGeometry(160, 32, 20);
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    uniforms: {
      top: { value: new THREE.Color(0x010309) },
      mid: { value: new THREE.Color(0x071527) },
      bottom: { value: new THREE.Color(0x02050b) },
    },
    vertexShader: `varying vec3 vPos; void main(){ vPos = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
    fragmentShader: `
      uniform vec3 top; uniform vec3 mid; uniform vec3 bottom; varying vec3 vPos;
      void main(){
        float h = normalize(vPos).y;
        vec3 c = mix(bottom, mid, smoothstep(-0.08, 0.2, h));
        c = mix(c, top, smoothstep(0.16, 0.85, h));
        gl_FragColor = vec4(c, 1.0);
      }`,
  });
  scene.add(new THREE.Mesh(geo, mat));

  const starGeo = new THREE.BufferGeometry();
  const arr = [];
  for (let i = 0; i < 260; i++) {
    const a = Math.random() * TAU;
    const y = 0.25 + Math.random() * 0.7;
    const r = Math.sqrt(1 - y * y) * 145;
    arr.push(Math.cos(a) * r, y * 145, Math.sin(a) * r);
  }
  starGeo.setAttribute('position', new THREE.Float32BufferAttribute(arr, 3));
  const stars = new THREE.Points(
    starGeo,
    new THREE.PointsMaterial({ color: 0x88a9d0, size: 0.45, transparent: true, opacity: 0.55, depthWrite: false, fog: false })
  );
  scene.add(stars);

  // distant city blocks
  const boxGeo = new THREE.BoxGeometry(1, 1, 1);
  const cityMat = new THREE.MeshStandardMaterial({
    color: 0x050b14,
    roughness: 0.9,
    metalness: 0.1,
    emissive: 0x071828,
    emissiveIntensity: 1,
  });
  const city = new THREE.InstancedMesh(boxGeo, cityMat, 46);
  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const s = new THREE.Vector3();
  const p = new THREE.Vector3();
  for (let i = 0; i < 46; i++) {
    const a = (i / 46) * TAU + Math.random() * 0.08;
    const r = 86 + Math.random() * 34;
    const h = 8 + Math.random() * 28;
    p.set(Math.cos(a) * r, h / 2 - 1, Math.sin(a) * r);
    q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), Math.random() * Math.PI);
    s.set(6 + Math.random() * 9, h, 6 + Math.random() * 9);
    m.compose(p, q, s);
    city.setMatrixAt(i, m);
  }
  city.instanceMatrix.needsUpdate = true;
  scene.add(city);
}

function createAds(group) {
  const lines = [
    ['NEON LEAGUE', '#44f3ff'],
    ['NO RULES · JUST GRAVITY', '#d7ff4a'],
    ['3V3 STREET FOOTBALL', '#ff4b9d'],
    ['PICK YOUR PLAYSTYLE', '#44f3ff'],
    ['DEMO BUILD', '#d7ff4a'],
  ];
  const textures = lines.map(([text, color]) => adTexture(text, color));
  const boardGeo = new THREE.PlaneGeometry(7.4, 1.04);
  for (const side of [-1, 1]) {
    for (let i = 0; i < 5; i++) {
      const tex = textures[(i + (side > 0 ? 1 : 0)) % textures.length];
      const mat = new THREE.MeshStandardMaterial({
        map: tex,
        emissive: 0xffffff,
        emissiveMap: tex,
        emissiveIntensity: 0.5,
        roughness: 0.5,
        side: THREE.DoubleSide,
      });
      const board = new THREE.Mesh(boardGeo, mat);
      board.position.set(side * (FIELD.halfWidth + 2.1), 1.12, -21.4 + i * 10.7);
      board.rotation.y = side > 0 ? -Math.PI / 2 : Math.PI / 2;
      group.add(board);
    }
  }
}

function createStands(group, glowTex) {
  const standMat = new THREE.MeshStandardMaterial({ color: 0x081220, roughness: 0.88, metalness: 0.12 });
  const railMat = new THREE.MeshBasicMaterial({ color: 0x123a55, transparent: true, opacity: 0.7 });
  for (const side of [-1, 1]) {
    const baseX = side * (FIELD.halfWidth + 5.4);
    for (let tier = 0; tier < 7; tier++) {
      const depth = 1.3;
      const h = 0.62;
      const step = new THREE.Mesh(new THREE.BoxGeometry(depth, h, FIELD.halfLength * 2 + 9), standMat);
      step.position.set(baseX + side * tier * 1.18, 0.35 + tier * 0.52, 0);
      step.receiveShadow = true;
      group.add(step);
      if (tier === 6) {
        const rail = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.05, FIELD.halfLength * 2 + 9), railMat);
        rail.position.set(baseX + side * tier * 1.18, 4.05, 0);
        group.add(rail);
      }
    }
    // corner glowing pylons
    for (const z of [-FIELD.halfLength - 3, FIELD.halfLength + 3]) {
      const pylon = new THREE.Mesh(
        new THREE.CylinderGeometry(0.1, 0.16, 2.6, 8),
        new THREE.MeshBasicMaterial({ color: side > 0 ? TEAMS.away.color : TEAMS.home.color })
      );
      pylon.position.set(baseX, 1.3, z);
      group.add(pylon);
      const glow = new THREE.Sprite(
        new THREE.SpriteMaterial({ map: glowTex, color: side > 0 ? TEAMS.away.color : TEAMS.home.color, transparent: true, opacity: 0.6, blending: THREE.AdditiveBlending, depthWrite: false })
      );
      glow.scale.set(2.4, 2.4, 1);
      glow.position.set(baseX, 2.8, z);
      group.add(glow);
    }
  }

  // crowd
  const count = 1000;
  const geo = new THREE.BoxGeometry(0.26, 0.5, 0.28);
  const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9, metalness: 0 });
  const crowd = new THREE.InstancedMesh(geo, mat, count);
  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const s = new THREE.Vector3(1, 1, 1);
  const p = new THREE.Vector3();
  const palette = [
    new THREE.Color(0x213044), new THREE.Color(0x2c3a51), new THREE.Color(0x1a2435),
    new THREE.Color(0x35e7ff), new THREE.Color(0xff3d8b), new THREE.Color(0xd7ff4a),
    new THREE.Color(0xd8e8ff), new THREE.Color(0x8f5bff),
  ];
  let n = 0;
  for (let i = 0; i < count * 2; i++) {
    if (n >= count) break;
    const side = Math.random() > 0.5 ? 1 : -1;
    const tier = Math.floor(Math.random() * 7);
    const baseX = side * (FIELD.halfWidth + 5.4);
    const x = baseX + side * tier * 1.18 + (Math.random() - 0.5) * 0.45;
    const y = 0.72 + tier * 0.52 + 0.26;
    const z = (Math.random() - 0.5) * (FIELD.halfLength * 2 + 7.5);
    if (Math.random() < 0.22) continue;
    p.set(x, y, z);
    q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), (Math.random() - 0.5) * 0.5);
    m.compose(p, q, s);
    crowd.setMatrixAt(n, m);
    crowd.setColorAt(n, palette[Math.floor(Math.random() * palette.length)]);
    n++;
  }
  crowd.count = n;
  crowd.instanceMatrix.needsUpdate = true;
  group.add(crowd);
}

export function createStadium(scene, renderer) {
  const world = new THREE.Group();
  const glowTex = radialGlowTexture();
  const detail = window.devicePixelRatio <= 1.5 && window.innerWidth < 900 ? 0.7 : 1;

  createSky(scene);

  const floor = new THREE.Mesh(
    new THREE.PlaneGeometry(220, 220),
    new THREE.MeshStandardMaterial({ color: 0x04080f, roughness: 0.95, metalness: 0.05 })
  );
  floor.rotation.x = -Math.PI / 2;
  floor.position.y = -0.06;
  floor.receiveShadow = true;
  world.add(floor);

  const pitch = new THREE.Mesh(
    new THREE.PlaneGeometry(FIELD.halfWidth * 2, FIELD.halfLength * 2),
    new THREE.MeshStandardMaterial({
      map: grassTexture(),
      roughness: 0.93,
      metalness: 0.02,
      color: 0xc5d9c8,
    })
  );
  pitch.rotation.x = -Math.PI / 2;
  pitch.receiveShadow = true;
  world.add(pitch);

  const markings = new THREE.Group();
  const hw = FIELD.halfWidth;
  const hl = FIELD.halfLength;
  addLine(markings, -hw, -hl, hw, -hl, 0.13);
  addLine(markings, -hw, hl, hw, hl, 0.13);
  addLine(markings, -hw, -hl, -hw, hl, 0.13);
  addLine(markings, hw, -hl, hw, hl, 0.13);
  addLine(markings, -hw, 0, hw, 0, 0.11);
  addRing(markings, 0, 0, 6, 0.1, 0xeafcff, 0.46);
  addRing(markings, 0, 0, 0.28, 0.15, 0xeafcff, 0.5);
  const boxW = 8.4;
  const boxD = 7;
  for (const dir of [-1, 1]) {
    addLine(markings, -boxW, dir * hl, -boxW, dir * (hl - boxD), 0.1);
    addLine(markings, boxW, dir * hl, boxW, dir * (hl - boxD), 0.1);
    addLine(markings, -boxW, dir * (hl - boxD), boxW, dir * (hl - boxD), 0.1);
    addRing(markings, 0, dir * (hl - 1.9), 0.16, 0.12, 0xeafcff, 0.52);
    // penalty arc
    addRing(markings, 0, dir * (hl - 5.2), 5.4, 0.09, 0xeafcff, 0.4, dir > 0 ? 0.35 : Math.PI + 0.35, Math.PI - 0.7);
  }
  for (const x of [-1, 1]) {
    for (const z of [-1, 1]) {
      addRing(markings, x * (hw - 1.1), z * (hl - 1.1), 1.05, 0.07, 0xeafcff, 0.35, x > 0 && z > 0 ? Math.PI : x < 0 && z > 0 ? Math.PI / 2 : x > 0 && z < 0 ? -Math.PI / 2 : 0, Math.PI / 2);
    }
  }
  world.add(markings);

  // luminous touchlines just inside the boards
  for (const side of [-1, 1]) {
    const strip = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.03, hl * 2), new THREE.MeshBasicMaterial({ color: side > 0 ? TEAMS.away.color : TEAMS.home.color, transparent: true, opacity: 0.32 }));
    strip.position.set(side * (hw - 0.17), 0.03, 0);
    world.add(strip);
  }

  // perimeter boards
  const boardMat = new THREE.MeshStandardMaterial({ color: 0x0a1726, roughness: 0.55, metalness: 0.5 });
  const ledMat = new THREE.MeshBasicMaterial({ color: 0x44f3ff, transparent: true, opacity: 0.55 });
  for (const side of [-1, 1]) {
    const wall = new THREE.Mesh(new THREE.BoxGeometry(0.3, FIELD.wallHeight, hl * 2 + 0.6), boardMat);
    wall.position.set(side * (hw + 0.16), FIELD.wallHeight / 2, 0);
    wall.castShadow = true;
    world.add(wall);
    const led = new THREE.Mesh(new THREE.BoxGeometry(0.33, 0.035, hl * 2 + 0.6), ledMat);
    led.position.set(side * (hw + 0.16), FIELD.wallHeight + 0.01, 0);
    world.add(led);
  }
  for (const dir of [-1, 1]) {
    const team = dir > 0 ? TEAMS.home : TEAMS.away;
    const goalW = FIELD.goalWidth / 2;
    const seg = hw - goalW;
    for (const side of [-1, 1]) {
      const wall = new THREE.Mesh(new THREE.BoxGeometry(seg, FIELD.wallHeight, 0.3), boardMat);
      wall.position.set(side * (goalW + seg / 2), FIELD.wallHeight / 2, dir * (hl + 0.16));
      wall.castShadow = true;
      world.add(wall);
      const led = new THREE.Mesh(new THREE.BoxGeometry(seg, 0.035, 0.33), new THREE.MeshBasicMaterial({ color: team.color, transparent: true, opacity: 0.55 }));
      led.position.set(side * (goalW + seg / 2), FIELD.wallHeight + 0.01, dir * (hl + 0.16));
      world.add(led);
    }
  }

  createAds(world);
  createStands(world, glowTex);

  // goals
  const homeGoal = createGoal(TEAMS.home, -hl);
  const awayGoal = createGoal(TEAMS.away, hl);
  world.add(homeGoal, awayGoal);

  // signs behind goals
  const signTex = signTexture();
  for (const dir of [-1, 1]) {
    const sign = new THREE.Mesh(
      new THREE.PlaneGeometry(13, 4.1),
      new THREE.MeshBasicMaterial({ map: signTex, color: 0xffffff, transparent: true, opacity: 0.95 })
    );
    sign.position.set(0, 5.6, dir * (hl + 9.6));
    sign.rotation.y = dir > 0 ? Math.PI : 0;
    world.add(sign);
    const bar = new THREE.Mesh(new THREE.BoxGeometry(13.6, 0.12, 0.12), new THREE.MeshBasicMaterial({ color: dir > 0 ? TEAMS.away.color : TEAMS.home.color }));
    bar.position.set(0, 3.48, dir * (hl + 9.62));
    world.add(bar);
  }

  // floodlights
  const corners = [
    [-hw - 12, -hl - 8],
    [hw + 12, -hl - 8],
    [-hw - 12, hl + 8],
    [hw + 12, hl + 8],
  ];
  for (const [x, z] of corners) {
    world.add(createFloodlight(x, z, new THREE.Vector3(0, 0, 0), glowTex));
  }

  // moon / haze
  const haze = new THREE.Sprite(
    new THREE.SpriteMaterial({ map: glowTex, color: 0x2d6f9e, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending, depthWrite: false, fog: false })
  );
  haze.scale.set(60, 60, 1);
  haze.position.set(-55, 30, -100);
  world.add(haze);

  scene.add(world);

  // lights
  const hemi = new THREE.HemisphereLight(0x8fc6ff, 0x0b1a13, 0.9);
  scene.add(hemi);

  const key = new THREE.DirectionalLight(0xf0f8ff, 2.3);
  key.position.set(16, 30, -8);
  key.castShadow = true;
  key.shadow.mapSize.set(detail > 0.8 ? 2048 : 1024, detail > 0.8 ? 2048 : 1024);
  key.shadow.camera.left = -34;
  key.shadow.camera.right = 34;
  key.shadow.camera.top = 38;
  key.shadow.camera.bottom = -38;
  key.shadow.camera.near = 4;
  key.shadow.camera.far = 70;
  key.shadow.bias = -0.0007;
  key.shadow.normalBias = 0.02;
  scene.add(key);

  const rim = new THREE.DirectionalLight(0x62c8ff, 0.8);
  rim.position.set(-22, 16, 24);
  scene.add(rim);

  const accentL = new THREE.PointLight(TEAMS.home.color, 24, 22, 2);
  accentL.position.set(0, 3.2, -hl - 1);
  scene.add(accentL);
  const accentR = new THREE.PointLight(TEAMS.away.color, 24, 22, 2);
  accentR.position.set(0, 3.2, hl + 1);
  scene.add(accentR);

  return {
    world,
    pitch,
    goals: [homeGoal, awayGoal],
    lights: { hemi, key, rim },
  };
}

import * as THREE from 'three';
import { FIELD, BASE } from './constants.js';

function ballTexture() {
  const c = document.createElement('canvas');
  c.width = 512;
  c.height = 256;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#f4f7f4';
  ctx.fillRect(0, 0, 512, 256);
  const grad = ctx.createLinearGradient(0, 0, 0, 256);
  grad.addColorStop(0, 'rgba(255,255,255,0.9)');
  grad.addColorStop(0.55, 'rgba(210,225,225,0.25)');
  grad.addColorStop(1, 'rgba(60,80,90,0.5)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 512, 256);

  const pent = (x, y, r, rot = 0, color = '#101820') => {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(rot);
    ctx.beginPath();
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2 - Math.PI / 2;
      const px = Math.cos(a) * r;
      const py = Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
    ctx.restore();
  };
  const rows = [
    [42, 62, 22], [150, 54, 24], [264, 66, 21], [372, 52, 24], [472, 64, 21],
    [96, 148, 24], [208, 142, 22], [320, 152, 24], [430, 144, 22],
    [38, 214, 22], [154, 206, 23], [266, 214, 22], [378, 204, 24], [480, 214, 21],
  ];
  for (const [x, y, r] of rows) pent(x, y, r, Math.random() * 2);
  // seams
  ctx.strokeStyle = 'rgba(40,55,65,0.22)';
  ctx.lineWidth = 1.4;
  for (let i = 0; i < 14; i++) {
    ctx.beginPath();
    ctx.moveTo(Math.random() * 512, Math.random() * 256);
    ctx.quadraticCurveTo(Math.random() * 512, Math.random() * 256, Math.random() * 512, Math.random() * 256);
    ctx.stroke();
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

export class Ball {
  constructor(scene) {
    this.radius = FIELD.ballRadius;
    this.pos = new THREE.Vector3(0, this.radius, 0);
    this.vel = new THREE.Vector3();
    this.spin = 0;
    this.owner = null;
    this.lastKicker = null;
    this.pickupLock = 0;
    this.kickLock = 0;
    this.airTime = 0;
    this.trailHistory = [];
    this.shotActive = false;

    this.mesh = new THREE.Mesh(
      new THREE.SphereGeometry(this.radius, 26, 20),
      new THREE.MeshStandardMaterial({
        map: ballTexture(),
        roughness: 0.36,
        metalness: 0.05,
        envMapIntensity: 0.8,
      })
    );
    this.mesh.castShadow = true;
    this.mesh.position.copy(this.pos);
    scene.add(this.mesh);

    // soft glow under the ball
    const glowCanvas = document.createElement('canvas');
    glowCanvas.width = 64;
    glowCanvas.height = 64;
    const gctx = glowCanvas.getContext('2d');
    const g = gctx.createRadialGradient(32, 32, 0, 32, 32, 32);
    g.addColorStop(0, 'rgba(255,255,255,0.5)');
    g.addColorStop(0.5, 'rgba(160,240,255,0.16)');
    g.addColorStop(1, 'rgba(0,0,0,0)');
    gctx.fillStyle = g;
    gctx.fillRect(0, 0, 64, 64);
    const glowTex = new THREE.CanvasTexture(glowCanvas);
    this.glow = new THREE.Mesh(
      new THREE.PlaneGeometry(1.6, 1.6),
      new THREE.MeshBasicMaterial({ map: glowTex, transparent: true, opacity: 0.42, depthWrite: false, blending: THREE.AdditiveBlending })
    );
    this.glow.rotation.x = -Math.PI / 2;
    scene.add(this.glow);

    this.trail = [];
    const trailMatBase = new THREE.MeshBasicMaterial({
      color: 0xd7ff4a,
      transparent: true,
      opacity: 0.3,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });
    for (let i = 0; i < 11; i++) {
      const mat = trailMatBase.clone();
      const mesh = new THREE.Mesh(new THREE.SphereGeometry(this.radius * (1 - i * 0.045), 10, 8), mat);
      mesh.visible = false;
      scene.add(mesh);
      this.trail.push(mesh);
    }

    this._axis = new THREE.Vector3();
    this._quat = new THREE.Quaternion();
    this._prev = new THREE.Vector3();
  }

  reset(x = 0, z = 0) {
    this.pos.set(x, this.radius, z);
    this.vel.set(0, 0, 0);
    this.spin = 0;
    this.owner = null;
    this.lastKicker = null;
    this.pickupLock = 0.2;
    this.kickLock = 0;
    this.airTime = 0;
    this.shotActive = false;
    this.trailHistory.length = 0;
    this.mesh.position.copy(this.pos);
    this.mesh.quaternion.identity();
    for (const t of this.trail) t.visible = false;
  }

  kick(dir, power, lift = 0, spin = 0) {
    this.owner = null;
    this.pickupLock = 0.2;
    this.kickLock = 0.16;
    this.vel.copy(dir).multiplyScalar(power);
    this.vel.y = lift;
    this.spin = spin;
    this.shotActive = power > 17;
    this.trailHistory.length = 0;
  }

  releaseFromOwner() {
    this.owner = null;
    this.pickupLock = 0.16;
  }

  update(dt) {
    this.pickupLock = Math.max(0, this.pickupLock - dt);
    this.kickLock = Math.max(0, this.kickLock - dt);

    if (!this.owner) {
      const v = this.vel;
      v.y -= BASE.gravity * dt;
      // Magnus bend from side spin
      if (Math.abs(this.spin) > 0.01) {
        const k = 0.012;
        const ax = this.spin * v.z * k;
        const az = -this.spin * v.x * k;
        v.x += ax * dt;
        v.z += az * dt;
        this.spin *= Math.exp(-0.55 * dt);
      }
      const drag = Math.exp(-0.11 * dt);
      v.x *= drag;
      v.z *= drag;
      if (v.y < 0) v.y *= Math.exp(-0.04 * dt);

      this.pos.addScaledVector(v, dt);

      if (this.pos.y <= this.radius) {
        this.pos.y = this.radius;
        if (v.y < -2.2) {
          v.y *= -0.56;
          v.x *= 0.86;
          v.z *= 0.86;
        } else {
          v.y = 0;
        }
        const roll = Math.exp(-1.05 * dt);
        v.x *= roll;
        v.z *= roll;
        if (Math.abs(v.x) < 0.06) v.x = 0;
        if (Math.abs(v.z) < 0.06) v.z = 0;
      }

      this.airTime += dt;
    } else {
      this.vel.multiplyScalar(0.5);
    }

    // spin visual
    const speed = this.vel.length();
    if (!this.owner && speed > 0.2) {
      this._axis.set(this.vel.z, 0, -this.vel.x);
      if (this._axis.lengthSq() > 0.0001) {
        this._axis.normalize();
        const angle = (Math.hypot(this.vel.x, this.vel.z) * dt) / this.radius;
        this._quat.setFromAxisAngle(this._axis, angle);
        this.mesh.quaternion.premultiply(this._quat);
      }
    }

    this.mesh.position.copy(this.pos);
    this.glow.position.set(this.pos.x, 0.035, this.pos.z);
    this.glow.material.opacity = 0.28 + Math.min(0.3, Math.max(0, 1 - this.pos.y / 6) * 0.22);

    this.updateTrail(dt, speed);
  }

  updateTrail(dt, speed) {
    const active = !this.owner && speed > 9;
    if (active) {
      this.trailHistory.unshift(this.pos.clone());
      if (this.trailHistory.length > 12) this.trailHistory.length = 12;
    } else {
      if (this.trailHistory.length) this.trailHistory.pop();
    }
    for (let i = 0; i < this.trail.length; i++) {
      const pt = this.trailHistory[i + 1];
      const t = this.trail[i];
      if (!pt || !active) {
        t.visible = false;
        continue;
      }
      t.visible = true;
      t.position.copy(pt);
      t.material.opacity = 0.34 * (1 - i / this.trail.length);
      const s = 0.9 - i * 0.045;
      t.scale.setScalar(Math.max(0.2, s));
    }
  }
}

import * as THREE from 'three';
import { BASE, FIELD } from './constants.js';

const TAU = Math.PI * 2;
const skinMats = new Map();
const hairMats = new Map();

function skinMat(color) {
  if (!skinMats.has(color)) skinMats.set(color, new THREE.MeshStandardMaterial({ color, roughness: 0.78, metalness: 0.02 }));
  return skinMats.get(color);
}
function hairMat(color) {
  if (!hairMats.has(color)) hairMats.set(color, new THREE.MeshStandardMaterial({ color, roughness: 0.9, metalness: 0 }));
  return hairMats.get(color);
}

function numberTexture(num, color, jersey) {
  const c = document.createElement('canvas');
  c.width = 128;
  c.height = 128;
  const ctx = c.getContext('2d');
  ctx.clearRect(0, 0, 128, 128);
  ctx.fillStyle = jersey;
  ctx.globalAlpha = 0.9;
  ctx.beginPath();
  ctx.roundRect(8, 8, 112, 112, 22);
  ctx.fill();
  ctx.globalAlpha = 1;
  ctx.fillStyle = color;
  ctx.font = '400 92px "Bebas Neue", Impact, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(String(num), 64, 70);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function blobTexture() {
  const c = document.createElement('canvas');
  c.width = 64;
  c.height = 64;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(32, 32, 2, 32, 32, 31);
  g.addColorStop(0, 'rgba(0,0,0,0.55)');
  g.addColorStop(0.55, 'rgba(0,0,0,0.26)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 64, 64);
  return new THREE.CanvasTexture(c);
}

let BLOB;
function shadowBlob() {
  if (!BLOB) BLOB = blobTexture();
  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(1.55, 1.55),
    new THREE.MeshBasicMaterial({ map: BLOB, transparent: true, opacity: 0.9, depthWrite: false })
  );
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.y = 0.02;
  return mesh;
}

function jerseyColor(team, keeper) {
  if (!keeper) return team.jersey;
  return team.id === 'home' ? 0xc7f24a : 0xffae3d;
}

export class Player {
  constructor({ scene, team, data, style, isKeeper = false, number = 7, quality = 1 }) {
    this.scene = scene;
    this.team = team;
    this.data = data;
    this.name = data.name;
    this.role = data.role;
    this.isKeeper = isKeeper;
    this.number = number;
    this.quality = quality;
    this.style = style;

    this.pos = new THREE.Vector3();
    this.vel = new THREE.Vector3();
    this.facing = team.dir > 0 ? 0 : Math.PI;
    this.targetFacing = this.facing;
    this.intent = new THREE.Vector2();
    this.sprinting = false;
    this.stamina = 100;
    this.controlled = false;
    this.isOwner = false;
    this.slideTimer = 0;
    this.skillTimer = 0;
    this.skillCooldown = 0;
    this.tackleCooldown = 0;
    this.kickCooldown = 0;
    this.charge = 0;
    this.action = { name: null, t: 0, dur: 0 };
    this.dive = { active: false, side: 1, t: 0 };
    this.runPhase = Math.random() * TAU;
    this.lastSpeed = 0;
    this.aiTimer = 0;
    this.aiRole = data.role;
    this.tackleActive = false;
    this.reactionTimer = 0;
    this.celebrate = false;

    this.stats = {
      speed: BASE.speed * (style?.speed ?? 1) * (isKeeper ? 0.94 : 1),
      sprint: BASE.sprintSpeed * (style?.sprint ?? 1) * (isKeeper ? 0.9 : 1),
      control: style?.control ?? 1,
      shotPower: style?.shotPower ?? 1,
      shotAccuracy: style?.shotAccuracy ?? 1,
      curve: style?.curve ?? 1,
      tackle: style?.tackle ?? 1,
      stamina: style?.stamina ?? 1,
      strength: style?.strength ?? 1,
    };

    this.buildModel();
  }

  buildModel() {
    const root = new THREE.Group();
    const visual = new THREE.Group();
    root.add(visual);
    visual.add(shadowBlob());

    const skin = skinMat(this.data.skin);
    const hair = hairMat(this.data.hair);
    const jersey = new THREE.MeshStandardMaterial({
      color: jerseyColor(this.team, this.isKeeper),
      roughness: 0.68,
      metalness: 0.04,
      emissive: jerseyColor(this.team, this.isKeeper),
      emissiveIntensity: 0.06,
    });
    const trimColor = this.isKeeper ? 0x101820 : this.team.trim;
    const trim = new THREE.MeshStandardMaterial({ color: trimColor, roughness: 0.5, metalness: 0.2 });
    const shorts = new THREE.MeshStandardMaterial({
      color: this.isKeeper ? 0x121a22 : this.team.dark,
      roughness: 0.75,
      metalness: 0.05,
    });
    const boot = new THREE.MeshStandardMaterial({
      color: this.team.id === 'home' ? 0xd7ff4a : 0xffd166,
      roughness: 0.35,
      metalness: 0.35,
      emissive: this.team.id === 'home' ? 0x49601a : 0x5c3c0c,
      emissiveIntensity: 0.6,
    });

    // legs
    const legGeo = new THREE.CapsuleGeometry(0.115, 0.5, 3, 8);
    const bootGeo = new THREE.BoxGeometry(0.21, 0.12, 0.38);
    this.legL = new THREE.Group();
    this.legR = new THREE.Group();
    for (const [leg, sx] of [[this.legL, -0.17], [this.legR, 0.17]]) {
      leg.position.set(sx, 0.88, 0);
      const shin = new THREE.Mesh(legGeo, skin);
      shin.position.y = -0.34;
      shin.castShadow = true;
      leg.add(shin);
      const sock = new THREE.Mesh(new THREE.CylinderGeometry(0.125, 0.115, 0.24, 8), trim);
      sock.position.y = -0.48;
      leg.add(sock);
      const foot = new THREE.Mesh(bootGeo, boot);
      foot.position.set(0, -0.7, 0.07);
      foot.castShadow = true;
      leg.add(foot);
      visual.add(leg);
    }

    // shorts
    const shortsMesh = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.27, 0.36), shorts);
    shortsMesh.position.y = 0.94;
    shortsMesh.castShadow = true;
    visual.add(shortsMesh);

    // torso
    const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.31, 0.48, 4, 10), jersey);
    torso.position.y = 1.36;
    torso.scale.set(1.13, 1, 0.8);
    torso.castShadow = true;
    visual.add(torso);

    // chest / shoulder trim
    const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.045, 0.6, 0.46), trim);
    stripe.position.set(0.22, 1.36, 0.02);
    stripe.rotation.z = -0.12;
    visual.add(stripe);
    const collar = new THREE.Mesh(new THREE.TorusGeometry(0.19, 0.028, 6, 14), trim);
    collar.rotation.x = Math.PI / 2;
    collar.position.y = 1.76;
    visual.add(collar);

    // arms
    const armGeo = new THREE.CapsuleGeometry(0.085, 0.45, 3, 8);
    this.armL = new THREE.Group();
    this.armR = new THREE.Group();
    for (const [arm, sx, side] of [[this.armL, -0.39, -1], [this.armR, 0.39, 1]]) {
      arm.position.set(sx, 1.6, 0);
      const limb = new THREE.Mesh(armGeo, skin);
      limb.position.y = -0.28;
      limb.castShadow = true;
      arm.add(limb);
      const sleeve = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.1, 0.18, 8), jersey);
      sleeve.position.y = -0.06;
      arm.add(sleeve);
      const hand = new THREE.Mesh(new THREE.SphereGeometry(0.085, 8, 6), this.isKeeper ? new THREE.MeshStandardMaterial({ color: this.team.id === 'home' ? 0xe8ffa4 : 0xffdfa0, roughness: 0.7 }) : skin);
      hand.position.y = -0.57;
      arm.add(hand);
      arm.rotation.z = side * 0.1;
      visual.add(arm);
    }

    // neck + head
    const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.085, 0.1, 0.12, 8), skin);
    neck.position.y = 1.81;
    visual.add(neck);
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.245, 16, 12), skin);
    head.position.y = 2.02;
    head.scale.set(0.94, 1.05, 0.94);
    head.castShadow = true;
    visual.add(head);

    // hair cap
    const hairMesh = new THREE.Mesh(new THREE.SphereGeometry(0.252, 14, 10, 0, TAU, 0, Math.PI * 0.52), hair);
    hairMesh.position.y = 2.04;
    hairMesh.rotation.x = -0.16;
    visual.add(hairMesh);
    if (Math.random() > 0.6) {
      const knot = new THREE.Mesh(new THREE.SphereGeometry(0.09, 8, 6), hair);
      knot.position.set(0, 2.28, -0.08);
      visual.add(knot);
    }

    // eyes
    const eyeMat = new THREE.MeshBasicMaterial({ color: 0x0a0d12 });
    for (const sx of [-0.085, 0.085]) {
      const eye = new THREE.Mesh(new THREE.SphereGeometry(0.022, 6, 5), eyeMat);
      eye.position.set(sx, 2.04, 0.215);
      visual.add(eye);
    }

    // number on back
    if (!this.isKeeper) {
      const tex = numberTexture(this.number, this.team.trim, `#${new THREE.Color(this.team.dark).getHexString()}`);
      const plane = new THREE.Mesh(
        new THREE.PlaneGeometry(0.42, 0.42),
        new THREE.MeshBasicMaterial({ map: tex, transparent: true, depthWrite: false, side: THREE.DoubleSide })
      );
      plane.position.set(0, 1.42, -0.3);
      plane.rotation.y = Math.PI;
      visual.add(plane);
    } else {
      // keeper gloves
      for (const arm of [this.armL, this.armR]) {
        const glove = new THREE.Mesh(
          new THREE.SphereGeometry(0.13, 8, 6),
          new THREE.MeshStandardMaterial({ color: this.team.id === 'home' ? 0xe6ff9c : 0xffe0a6, roughness: 0.65 })
        );
        glove.position.y = -0.61;
        glove.scale.set(1, 1.25, 0.7);
        arm.add(glove);
      }
    }

    // controlled / owner rings
    this.ring = new THREE.Mesh(
      new THREE.RingGeometry(0.58, 0.7, 36),
      new THREE.MeshBasicMaterial({ color: 0xd7ff4a, transparent: true, opacity: 0.9, depthWrite: false, side: THREE.DoubleSide })
    );
    this.ring.rotation.x = -Math.PI / 2;
    this.ring.position.y = 0.025;
    this.ring.visible = false;
    root.add(this.ring);

    this.ringGlow = new THREE.Mesh(
      new THREE.RingGeometry(0.7, 0.86, 36),
      new THREE.MeshBasicMaterial({ color: 0xd7ff4a, transparent: true, opacity: 0.18, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending })
    );
    this.ringGlow.rotation.x = -Math.PI / 2;
    this.ringGlow.position.y = 0.018;
    this.ringGlow.visible = false;
    root.add(this.ringGlow);

    this.chevron = new THREE.Mesh(
      new THREE.ConeGeometry(0.14, 0.26, 4),
      new THREE.MeshBasicMaterial({ color: 0xd7ff4a, transparent: true, opacity: 0.95, depthWrite: false })
    );
    this.chevron.rotation.x = Math.PI;
    this.chevron.rotation.y = Math.PI / 4;
    this.chevron.position.y = 2.72;
    this.chevron.visible = false;
    root.add(this.chevron);

    // pass target ring
    this.targetRing = new THREE.Mesh(
      new THREE.RingGeometry(0.85, 0.98, 40),
      new THREE.MeshBasicMaterial({ color: 0x44f3ff, transparent: true, opacity: 0.6, depthWrite: false, side: THREE.DoubleSide })
    );
    this.targetRing.rotation.x = -Math.PI / 2;
    this.targetRing.position.y = 0.02;
    this.targetRing.visible = false;
    root.add(this.targetRing);

    this.root = root;
    this.visual = visual;
    this.mesh = root;
    this.scene.add(root);
  }

  setControlled(v) {
    this.controlled = v;
    this.ring.visible = v;
    this.ringGlow.visible = v;
    this.chevron.visible = v;
  }

  setOwner(v, color = 0xd7ff4a) {
    this.isOwner = v;
    if (v && !this.controlled) {
      this.ring.visible = true;
      this.ring.material.color.setHex(color);
      this.ringGlow.material.color.setHex(color);
      this.ringGlow.visible = true;
    } else if (!v && !this.controlled) {
      this.ring.visible = false;
      this.ringGlow.visible = false;
    }
  }

  setPosition(x, z, facing) {
    this.pos.set(x, 0, z);
    this.vel.set(0, 0, 0);
    this.slideTimer = 0;
    this.skillTimer = 0;
    this.tackleActive = false;
    this.action = { name: null, t: 0, dur: 0 };
    if (facing !== undefined) {
      this.facing = facing;
      this.targetFacing = facing;
    }
    this.root.position.set(x, 0, z);
    this.root.rotation.y = this.facing;
  }

  play(name, dur) {
    this.action = { name, t: 0, dur };
  }

  startSlide(dirX, dirZ) {
    this.slideTimer = 0.44;
    this.tackleActive = true;
    this.tackleCooldown = 1.15;
    this.vel.set(dirX * 15.5, 0, dirZ * 15.5);
    this.targetFacing = Math.atan2(dirX, dirZ);
    this.facing = this.targetFacing;
    this.play('slide', 0.62);
  }

  startSkill(dirX, dirZ) {
    this.skillTimer = 0.34;
    this.skillCooldown = 1.05 * (this.style?.skillCooldown ?? 1);
    const len = Math.hypot(dirX, dirZ) || 1;
    this.vel.set((dirX / len) * 16.2, 0, (dirZ / len) * 16.2);
    this.targetFacing = Math.atan2(dirX, dirZ);
    this.facing = this.targetFacing;
    this.play('skill', 0.38);
  }

  update(dt, moveX, moveZ, sprint, speedMul = 1) {
    this.skillCooldown = Math.max(0, this.skillCooldown - dt);
    this.tackleCooldown = Math.max(0, this.tackleCooldown - dt);
    this.kickCooldown = Math.max(0, this.kickCooldown - dt);
    this.slideTimer = Math.max(0, this.slideTimer - dt);
    this.skillTimer = Math.max(0, this.skillTimer - dt);

    const len = Math.hypot(moveX, moveZ);
    if (this.slideTimer > 0) {
      this.vel.multiplyScalar(Math.exp(-2.1 * dt));
    } else if (this.skillTimer > 0) {
      this.vel.multiplyScalar(Math.exp(-1.4 * dt));
    } else if (len > 0.04) {
      const nx = moveX / len;
      const nz = moveZ / len;
      const canSprint = sprint && this.stamina > 2 && this.charge < 0.3;
      const max = (canSprint ? this.stats.sprint : this.stats.speed) * speedMul * (this.charge > 0.05 ? 0.74 : 1);
      const desiredX = nx * max;
      const desiredZ = nz * max;
      const rate = 1 - Math.exp(-BASE.accel * dt);
      this.vel.x += (desiredX - this.vel.x) * rate;
      this.vel.z += (desiredZ - this.vel.z) * rate;
      this.targetFacing = Math.atan2(nx, nz);
      this.sprinting = canSprint;
    } else {
      const rate = 1 - Math.exp(-BASE.accel * 1.35 * dt);
      this.vel.x -= this.vel.x * rate;
      this.vel.z -= this.vel.z * rate;
      this.sprinting = false;
    }

    if (this.slideTimer > 0) this.sprinting = false;

    // stamina
    if (this.sprinting && len > 0.1) {
      this.stamina -= (BASE.staminaDrain / this.stats.stamina) * dt;
    } else {
      const regen = len < 0.1 ? BASE.staminaRegen * 1.6 : BASE.staminaRegen;
      this.stamina += (regen * Math.min(2, this.stats.stamina)) * dt;
    }
    this.stamina = Math.max(0, Math.min(100, this.stamina));
    if (this.stamina <= 0) this.sprinting = false;

    this.pos.x += this.vel.x * dt;
    this.pos.z += this.vel.z * dt;

    // turn toward intent / velocity
    let target = this.targetFacing;
    const speed = Math.hypot(this.vel.x, this.vel.z);
    if (speed > 0.8 && this.slideTimer <= 0) target = Math.atan2(this.vel.x, this.vel.z);
    let diff = ((target - this.facing + Math.PI * 3) % TAU) - Math.PI;
    const turn = (this.skillTimer > 0 ? 14 : BASE.turn) * dt;
    this.facing += THREE.MathUtils.clamp(diff, -turn, turn);

    this.root.position.set(this.pos.x, 0, this.pos.z);
    this.root.rotation.y = this.facing;

    this.updateAnimation(dt, speed);
    this.lastSpeed = speed;
  }

  updateAnimation(dt, speed) {
    const t = performance.now() / 1000;
    const a = this.action;
    if (a.name) {
      a.t += dt;
      if (a.t >= a.dur) {
        a.name = null;
        a.t = 0;
      }
    }
    const running = speed > 0.35;
    this.runPhase += dt * (2.2 + Math.min(speed, 14) * 1.42);
    const ratio = Math.min(1, speed / 12);
    const swing = running ? Math.sin(this.runPhase) * (0.52 + ratio * 0.55) : Math.sin(t * 1.6 + this.number) * 0.06;

    let lean = ratio * 0.16;
    let bob = running ? Math.abs(Math.sin(this.runPhase * 2)) * 0.055 * ratio : Math.sin(t * 1.8 + this.number) * 0.012;
    let bodyY = 0;
    let bodyZ = 0;

    this.legL.rotation.x = swing;
    this.legR.rotation.x = -swing;
    this.armL.rotation.x = -swing * 0.8;
    this.armR.rotation.x = swing * 0.8;
    this.armL.rotation.z = -0.1;
    this.armR.rotation.z = 0.1;
    this.visual.rotation.z = 0;
    this.visual.rotation.x = lean;
    this.visual.scale.set(1, 1, 1);

    if (this.charge > 0.03) {
      bodyY = -0.09;
      lean += 0.05;
      this.legL.rotation.x = -0.35;
      this.legR.rotation.x = 0.35;
      this.armL.rotation.z = -0.6;
      this.armR.rotation.z = 0.6;
      this.visual.rotation.x = lean;
    }

    if (a.name === 'kick') {
      const p = a.t / a.dur;
      const kick = Math.sin(Math.min(1, p * 1.15) * Math.PI);
      this.legR.rotation.x = 0.9 * kick;
      this.legL.rotation.x = -0.45 * kick;
      this.visual.rotation.x = lean + 0.07 * kick;
      this.armL.rotation.z = -0.9 * kick;
    } else if (a.name === 'slide') {
      const p = Math.min(1, a.t / a.dur);
      const tilt = Math.sin(Math.min(1, p * 1.5) * Math.PI * 0.5);
      this.visual.rotation.z = -1.22 * tilt;
      bodyY = -0.44 * tilt;
      this.legL.rotation.x = 0.8;
      this.legR.rotation.x = 1.2;
      this.armL.rotation.z = -1.4;
      this.armR.rotation.z = 0.3;
    } else if (a.name === 'skill') {
      const p = a.t / a.dur;
      const spin = Math.sin(p * Math.PI);
      bodyY = Math.sin(p * Math.PI) * 0.14;
      this.visual.rotation.y = p * Math.PI * 2;
      this.legL.rotation.x = 0.9 * spin;
      this.legR.rotation.x = -0.7 * spin;
      this.armL.rotation.z = -0.8 - spin;
      this.armR.rotation.z = 0.8 + spin;
      this.visual.rotation.x = 0.12;
    } else if (a.name === 'celebrate') {
      const p = a.t / a.dur;
      const jump = Math.abs(Math.sin(p * Math.PI * 5)) * 0.24;
      bodyY = jump;
      this.visual.rotation.x = -0.06;
      this.armL.rotation.z = -2.5 + Math.sin(t * 14) * 0.2;
      this.armR.rotation.z = 2.5 - Math.sin(t * 14) * 0.2;
      this.armL.rotation.x = -0.2;
      this.armR.rotation.x = -0.2;
      this.legL.rotation.x = 0.2 + jump;
      this.legR.rotation.x = -0.2 - jump;
    } else if (a.name === 'dejected') {
      this.visual.rotation.x = 0.22;
      bodyY = -0.06;
      this.armL.rotation.z = -0.2;
      this.armR.rotation.z = 0.2;
      this.armL.rotation.x = 0.3;
      this.armR.rotation.x = 0.3;
    }

    if (this.dive.active) {
      const p = Math.min(1, this.dive.t / 0.55);
      this.visual.rotation.z = -this.dive.side * (0.2 + p * 1.25);
      bodyY = -0.28 + Math.abs(Math.sin(p * Math.PI)) * 0.5;
      this.armL.rotation.z = -2.4;
      this.armR.rotation.z = 2.4;
      this.armL.rotation.x = -0.6;
      this.armR.rotation.x = -0.6;
      this.legL.rotation.x = 0.7;
      this.legR.rotation.x = -0.4;
    }

    this.visual.position.y = bodyY + bob;
    this.visual.position.z = bodyZ;
    if (a.name === 'skill') {
      this.visual.rotation.y += 0;
    } else {
      this.visual.rotation.y *= Math.exp(-10 * dt);
    }

    // controlled ring pulse
    if (this.controlled) {
      const pulse = 1 + Math.sin(t * 4.5) * 0.06;
      this.ring.scale.setScalar(pulse);
      this.ringGlow.scale.setScalar(1 + Math.sin(t * 4.5 + 1) * 0.1);
      this.chevron.position.y = 2.72 + Math.sin(t * 3) * 0.07;
      this.chevron.rotation.y += dt * 1.4;
    }
    if (this.isOwner && !this.controlled) {
      this.ring.scale.setScalar(1 + Math.sin(t * 5) * 0.05);
    }
  }

  setDive(side) {
    if (this.dive.active) return;
    this.dive.active = true;
    this.dive.side = side;
    this.dive.t = 0;
    this.play('dive', 0.7);
  }

  updateDive(dt) {
    if (!this.dive.active) return;
    this.dive.t += dt;
    if (this.dive.t > 0.75) {
      this.dive.active = false;
      this.dive.t = 0;
    }
  }

  celebrateFor(dur = 2.2) {
    this.play('celebrate', dur);
  }

  dispose() {
    this.scene.remove(this.root);
  }
}

export function clampToPitch(pos, margin = 1) {
  pos.x = THREE.MathUtils.clamp(pos.x, -FIELD.halfWidth + margin, FIELD.halfWidth - margin);
  pos.z = THREE.MathUtils.clamp(pos.z, -FIELD.halfLength + margin, FIELD.halfLength - margin);
}

import * as THREE from 'three';

const KEY_ACTIONS = {
  Space: 'shoot',
  KeyK: 'pass',
  KeyJ: 'skill',
  ShiftLeft: 'sprint',
  ShiftRight: 'sprint',
};

export class Input {
  constructor({ onPause, onGesture } = {}) {
    this.onPause = onPause;
    this.onGesture = onGesture;
    this.keys = new Set();
    this.down = new Map();
    this.pressed = new Set();
    this.released = new Set();
    this.stick = new THREE.Vector2();
    this.stickActive = false;
    this.touchButtons = new Map();
    this.gamepad = null;
    this.gamepadPrev = {};
    this.gestureSent = false;

    this._bindKeyboard();
    this._bindTouch();

    window.addEventListener('gamepadconnected', (e) => { this.gamepad = e.gamepad; });
    window.addEventListener('gamepaddisconnected', () => { this.gamepad = null; });
  }

  _gesture() {
    if (!this.gestureSent) {
      this.gestureSent = true;
      this.onGesture?.();
    }
  }

  _bindKeyboard() {
    window.addEventListener('keydown', (e) => {
      const gameKey = KEY_ACTIONS[e.code] || ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Escape', 'KeyP', 'KeyW', 'KeyA', 'KeyS', 'KeyD'].includes(e.code);
      if (gameKey) e.preventDefault();
      if (e.repeat) return;
      if (e.code === 'Escape' || e.code === 'KeyP') {
        this.onPause?.();
        return;
      }
      this._gesture();
      this.keys.add(e.code);
      const action = KEY_ACTIONS[e.code];
      if (action) this._setDown(action, `key:${e.code}`);
    });

    window.addEventListener('keyup', (e) => {
      this.keys.delete(e.code);
      const action = KEY_ACTIONS[e.code];
      if (action) this._setUp(action, `key:${e.code}`);
    });

    window.addEventListener('blur', () => {
      for (const action of this.down.keys()) {
        for (const source of [...this.down.get(action)]) this._setUp(action, source);
      }
      this.keys.clear();
    });
  }

  _bindTouch() {
    const buttons = document.querySelectorAll('.tbtn[data-action]');
    buttons.forEach((btn) => {
      const action = btn.dataset.action;
      btn.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        e.stopPropagation();
        this._gesture();
        btn.setPointerCapture?.(e.pointerId);
        btn.classList.add('is-down');
        this.touchButtons.set(e.pointerId, { action, btn });
        this._setDown(action, `touch:${e.pointerId}`);
      });
      const release = (e) => {
        const entry = this.touchButtons.get(e.pointerId);
        if (!entry) return;
        e.preventDefault();
        btn.classList.remove('is-down');
        this.touchButtons.delete(e.pointerId);
        this._setUp(entry.action, `touch:${e.pointerId}`);
      };
      btn.addEventListener('pointerup', release);
      btn.addEventListener('pointercancel', release);
      btn.addEventListener('lostpointercapture', (e) => {
        const entry = this.touchButtons.get(e.pointerId);
        if (entry) {
          btn.classList.remove('is-down');
          this.touchButtons.delete(e.pointerId);
          this._setUp(entry.action, `touch:${e.pointerId}`);
        }
      });
      btn.addEventListener('contextmenu', (e) => e.preventDefault());
    });

    const zone = document.getElementById('stickBase');
    if (!zone) return;
    const knob = document.getElementById('stickKnob');
    let pointerId = null;
    let cx = 0;
    let cy = 0;

    const setStick = (clientX, clientY) => {
      const rect = zone.getBoundingClientRect();
      cx = rect.left + rect.width / 2;
      cy = rect.top + rect.height / 2;
      const radius = rect.width * 0.36;
      let dx = clientX - cx;
      let dy = clientY - cy;
      const len = Math.hypot(dx, dy);
      if (len > radius) {
        dx = (dx / len) * radius;
        dy = (dy / len) * radius;
      }
      this.stick.set(dx / radius, -dy / radius);
      const dead = 0.12;
      if (Math.abs(this.stick.x) < dead) this.stick.x = 0;
      if (Math.abs(this.stick.y) < dead) this.stick.y = 0;
      const mag = Math.hypot(this.stick.x, this.stick.y);
      if (mag > 1) this.stick.multiplyScalar(1 / mag);
      if (knob) knob.style.transform = `translate(${dx}px, ${dy}px)`;
    };

    const reset = () => {
      pointerId = null;
      this.stickActive = false;
      this.stick.set(0, 0);
      if (knob) knob.style.transform = 'translate(0px, 0px)';
    };

    zone.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      e.stopPropagation();
      this._gesture();
      pointerId = e.pointerId;
      this.stickActive = true;
      zone.setPointerCapture?.(e.pointerId);
      setStick(e.clientX, e.clientY);
    });
    zone.addEventListener('pointermove', (e) => {
      if (e.pointerId !== pointerId) return;
      e.preventDefault();
      setStick(e.clientX, e.clientY);
    });
    zone.addEventListener('pointerup', (e) => {
      if (e.pointerId !== pointerId) return;
      e.preventDefault();
      reset();
    });
    zone.addEventListener('pointercancel', (e) => {
      if (e.pointerId !== pointerId) return;
      reset();
    });
    zone.addEventListener('lostpointercapture', (e) => {
      if (e.pointerId === pointerId) reset();
    });
    zone.addEventListener('contextmenu', (e) => e.preventDefault());

    window.addEventListener('blur', reset);
    document.addEventListener('visibilitychange', reset);
  }

  _setDown(action, source) {
    if (!this.down.has(action)) this.down.set(action, new Set());
    const set = this.down.get(action);
    if (set.has(source)) return;
    set.add(source);
    if (set.size === 1) this.pressed.add(action);
  }

  _setUp(action, source) {
    const set = this.down.get(action);
    if (!set || !set.has(source)) return;
    set.delete(source);
    if (set.size === 0) this.released.add(action);
  }

  poll() {
    // gamepad support
    if (!this.gamepad) {
      const pads = navigator.getGamepads?.();
      this.gamepad = pads ? [...pads].find(Boolean) : null;
    }
    if (!this.gamepad) return;
    const pad = this.gamepad;
    const map = { 0: 'shoot', 1: 'pass', 2: 'skill', 5: 'sprint', 7: 'sprint' };
    for (const [index, action] of Object.entries(map)) {
      const btn = pad.buttons[Number(index)];
      const active = !!btn && (btn.pressed || btn.value > 0.4);
      const key = `pad:${index}`;
      if (active && !this.gamepadPrev[key]) {
        this._gesture();
        this._setDown(action, key);
      } else if (!active && this.gamepadPrev[key]) {
        this._setUp(action, key);
      }
      this.gamepadPrev[key] = active;
    }
    const ax = pad.axes[0] ?? 0;
    const ay = pad.axes[1] ?? 0;
    if (Math.hypot(ax, ay) > 0.18 && !this.stickActive) {
      this.stick.set(ax, -ay);
    }
  }

  isDown(action) {
    const set = this.down.get(action);
    return !!set && set.size > 0;
  }

  wasPressed(action) {
    return this.pressed.has(action);
  }

  wasReleased(action) {
    return this.released.has(action);
  }

  moveAxes() {
    let x = this.stick.x;
    let y = this.stick.y;
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) x -= 1;
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) x += 1;
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) y += 1;
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) y -= 1;
    const len = Math.hypot(x, y);
    if (len > 1) {
      x /= len;
      y /= len;
    }
    return { x, y };
  }

  endFrame() {
    this.pressed.clear();
    this.released.clear();
  }
}

import * as THREE from 'three';

const MAX = 800;

export class Effects {
  constructor(scene, ball) {
    this.scene = scene;
    this.ball = ball;
    this.particles = [];
    this.cursor = 0;
    this.rings = [];
    this.popups = [];

    const geo = new THREE.BufferGeometry();
    this.positions = new Float32Array(MAX * 3);
    this.colors = new Float32Array(MAX * 3);
    this.sizes = new Float32Array(MAX);
    this.alphas = new Float32Array(MAX);
    geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(this.colors, 3));
    geo.setAttribute('size', new THREE.BufferAttribute(this.sizes, 1));
    geo.setAttribute('alpha', new THREE.BufferAttribute(this.alphas, 1));
    geo.setDrawRange(0, MAX);

    const tex = this._dotTexture();
    this.material = new THREE.ShaderMaterial({
      uniforms: {
        uScale: { value: 500 },
        uMap: { value: tex },
      },
      vertexShader: `
        attribute float size;
        attribute float alpha;
        varying vec3 vColor;
        varying float vAlpha;
        uniform float uScale;
        void main(){
          vColor = color;
          vAlpha = alpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = clamp(size * uScale / max(0.4, -mv.z), 1.0, 80.0);
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: `
        uniform sampler2D uMap;
        varying vec3 vColor;
        varying float vAlpha;
        void main(){
          vec4 t = texture2D(uMap, gl_PointCoord);
          if (t.a < 0.03) discard;
          gl_FragColor = vec4(vColor, t.a * vAlpha);
        }
      `,
      vertexColors: true,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });

    this.points = new THREE.Points(geo, this.material);
    this.points.frustumCulled = false;
    scene.add(this.points);

    for (let i = 0; i < MAX; i++) {
      this.particles.push({
        active: false,
        pos: new THREE.Vector3(),
        vel: new THREE.Vector3(),
        life: 0,
        maxLife: 1,
        size: 0.2,
        color: new THREE.Color(),
        gravity: 0,
        drag: 0,
        fade: 1,
      });
      this.alphas[i] = 0;
    }

    // shock rings
    for (let i = 0; i < 7; i++) {
      const mat = new THREE.MeshBasicMaterial({
        color: 0xd7ff4a,
        transparent: true,
        opacity: 0,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        side: THREE.DoubleSide,
      });
      const ring = new THREE.Mesh(new THREE.RingGeometry(0.38, 0.52, 40), mat);
      ring.rotation.x = -Math.PI / 2;
      ring.visible = false;
      scene.add(ring);
      this.rings.push({ mesh: ring, t: 0, life: 0.55, active: false, maxScale: 6 });
    }

    this.tmp = new THREE.Color();
  }

  _dotTexture() {
    const c = document.createElement('canvas');
    c.width = 64;
    c.height = 64;
    const ctx = c.getContext('2d');
    const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
    g.addColorStop(0, 'rgba(255,255,255,1)');
    g.addColorStop(0.35, 'rgba(255,255,255,0.92)');
    g.addColorStop(0.7, 'rgba(255,255,255,0.32)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, 64, 64);
    return new THREE.CanvasTexture(c);
  }

  setViewport(height) {
    this.material.uniforms.uScale.value = height * 0.62;
  }

  spawn(pos, opts = {}) {
    const p = this.particles[this.cursor];
    this.cursor = (this.cursor + 1) % MAX;
    p.active = true;
    p.pos.copy(pos);
    p.vel.set(opts.vx ?? 0, opts.vy ?? 0, opts.vz ?? 0);
    p.life = opts.life ?? 0.6;
    p.maxLife = p.life;
    p.size = opts.size ?? 0.18;
    p.color.set(opts.color ?? 0xffffff);
    p.gravity = opts.gravity ?? 0;
    p.drag = opts.drag ?? 0.4;
    p.fade = opts.fade ?? 1;
    return p;
  }

  burst(pos, count = 16, color = 0xffffff, power = 4, opts = {}) {
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const up = Math.random() * 0.9;
      const sp = power * (0.35 + Math.random() * 0.8);
      this.spawn(pos, {
        vx: Math.cos(a) * sp,
        vy: up * sp * (opts.up ?? 0.7),
        vz: Math.sin(a) * sp,
        life: 0.35 + Math.random() * (opts.life ?? 0.5),
        size: (0.12 + Math.random() * 0.22) * (opts.size ?? 1),
        color: Array.isArray(color) ? color[Math.floor(Math.random() * color.length)] : color,
        gravity: opts.gravity ?? 5,
        drag: 1.6,
      });
    }
  }

  kickBurst(pos, color = 0xffffff, power = 1) {
    this.burst(pos, Math.round(10 + power * 10), color, 3 + power * 3, { life: 0.4, gravity: 4, size: 1.1 });
    this.ring(pos, color, 2.6 + power * 1.4);
  }

  ring(pos, color = 0xd7ff4a, maxScale = 5) {
    const r = this.rings.find((x) => !x.active) || this.rings[0];
    r.active = true;
    r.t = 0;
    r.maxScale = maxScale;
    r.mesh.material.color.set(color);
    r.mesh.material.opacity = 0.7;
    r.mesh.position.set(pos.x, 0.04, pos.z);
    r.mesh.scale.setScalar(1);
    r.mesh.visible = true;
  }

  confetti(pos, colors = [0xd7ff4a, 0x44f3ff, 0xffffff, 0xff4b9d]) {
    for (let i = 0; i < 150; i++) {
      const a = Math.random() * Math.PI * 2;
      const sp = 2 + Math.random() * 9;
      this.spawn(new THREE.Vector3(pos.x + (Math.random() - 0.5) * 6, 5 + Math.random() * 8, pos.z + (Math.random() - 0.5) * 4), {
        vx: Math.cos(a) * sp * 0.5,
        vy: 2 + Math.random() * 5,
        vz: Math.sin(a) * sp * 0.5,
        life: 1.8 + Math.random() * 2.4,
        size: 0.12 + Math.random() * 0.18,
        color: colors[Math.floor(Math.random() * colors.length)],
        gravity: 4.5,
        drag: 0.35,
      });
    }
    for (let i = 0; i < 40; i++) {
      const a = Math.random() * Math.PI * 2;
      this.spawn(new THREE.Vector3(pos.x, 0.2, pos.z), {
        vx: Math.cos(a) * 2.5,
        vy: 5 + Math.random() * 5,
        vz: Math.sin(a) * 2.5,
        life: 1.2 + Math.random(),
        size: 0.16,
        color: 0xffffff,
        gravity: 3,
        drag: 0.8,
      });
    }
  }

  trailPuff(pos, color = 0xd7ff4a) {
    this.spawn(pos, {
      vx: (Math.random() - 0.5) * 2,
      vy: 0.4 + Math.random(),
      vz: (Math.random() - 0.5) * 2,
      life: 0.45,
      size: 0.16 + Math.random() * 0.14,
      color,
      gravity: -1,
      drag: 1.4,
    });
  }

  update(dt) {
    const pos = this.positions;
    const colors = this.colors;
    const sizes = this.sizes;
    const alphas = this.alphas;
    for (let i = 0; i < MAX; i++) {
      const p = this.particles[i];
      if (!p.active) {
        alphas[i] = 0;
        continue;
      }
      p.life -= dt;
      if (p.life <= 0) {
        p.active = false;
        alphas[i] = 0;
        continue;
      }
      p.vel.y -= p.gravity * dt;
      p.vel.multiplyScalar(Math.exp(-p.drag * dt));
      p.pos.addScaledVector(p.vel, dt);
      if (p.pos.y < 0.04) {
        p.pos.y = 0.04;
        p.vel.y = Math.abs(p.vel.y) * 0.3;
        p.vel.x *= 0.8;
        p.vel.z *= 0.8;
      }
      const k = p.life / p.maxLife;
      pos[i * 3] = p.pos.x;
      pos[i * 3 + 1] = p.pos.y;
      pos[i * 3 + 2] = p.pos.z;
      colors[i * 3] = p.color.r;
      colors[i * 3 + 1] = p.color.g;
      colors[i * 3 + 2] = p.color.b;
      sizes[i] = p.size * (0.4 + k * 0.8);
      alphas[i] = Math.min(1, k * 2.2) * p.fade;
    }
    this.points.geometry.attributes.position.needsUpdate = true;
    this.points.geometry.attributes.color.needsUpdate = true;
    this.points.geometry.attributes.size.needsUpdate = true;
    this.points.geometry.attributes.alpha.needsUpdate = true;

    for (const r of this.rings) {
      if (!r.active) continue;
      r.t += dt;
      const k = r.t / r.life;
      if (k >= 1) {
        r.active = false;
        r.mesh.visible = false;
        continue;
      }
      r.mesh.scale.setScalar(1 + (r.maxScale - 1) * (1 - Math.pow(1 - k, 2)));
      r.mesh.material.opacity = 0.7 * (1 - k);
    }
  }
}

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.crowdGain = null;
    this.muted = localStorage.getItem('neon-muted') === '1';
    this.ready = false;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.7;
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -14;
    comp.knee.value = 22;
    comp.ratio.value = 4;
    comp.attack.value = 0.004;
    comp.release.value = 0.2;
    this.master.connect(comp);
    comp.connect(this.ctx.destination);
    this._buildCrowd();
    this.ready = true;
  }

  setMuted(muted) {
    this.muted = muted;
    localStorage.setItem('neon-muted', muted ? '1' : '0');
    if (this.master) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.linearRampToValueAtTime(muted ? 0 : 0.7, this.ctx.currentTime + 0.15);
    }
  }

  toggleMuted() {
    this.setMuted(!this.muted);
    return this.muted;
  }

  _noiseBuffer(seconds = 2) {
    const len = Math.floor(this.ctx.sampleRate * seconds);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      data[i] = last * 3.2;
    }
    return buf;
  }

  _buildCrowd() {
    const src = this.ctx.createBufferSource();
    src.buffer = this._noiseBuffer(4);
    src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 480;
    filter.Q.value = 0.55;
    this.crowdGain = this.ctx.createGain();
    this.crowdGain.gain.value = 0.045;
    src.connect(filter);
    filter.connect(this.crowdGain);
    this.crowdGain.connect(this.master);
    src.start();

    const src2 = this.ctx.createBufferSource();
    src2.buffer = this._noiseBuffer(3);
    src2.loop = true;
    const filter2 = this.ctx.createBiquadFilter();
    filter2.type = 'lowpass';
    filter2.frequency.value = 180;
    const g2 = this.ctx.createGain();
    g2.gain.value = 0.05;
    src2.connect(filter2);
    filter2.connect(g2);
    g2.connect(this.master);
    src2.start();
  }

  _tone({ type = 'sine', freq = 440, freqEnd, gain = 0.2, dur = 0.2, delay = 0, attack = 0.006, detune = 0 }) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (freqEnd !== undefined) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freqEnd), t + dur);
    if (detune) osc.detune.value = detune;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g);
    g.connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.03);
  }

  _noiseHit({ gain = 0.2, dur = 0.12, type = 'bandpass', freq = 900, q = 1, delay = 0 }) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this._noiseBuffer(Math.max(0.2, dur + 0.1));
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = freq;
    filter.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter);
    filter.connect(g);
    g.connect(this.master);
    src.start(t);
    src.stop(t + dur + 0.02);
  }

  kick(power = 1) {
    this._tone({ type: 'sine', freq: 150 + power * 40, freqEnd: 45, gain: 0.32 + power * 0.2, dur: 0.16 });
    this._noiseHit({ gain: 0.14, dur: 0.06, freq: 1800, q: 0.9 });
    this._noiseHit({ gain: 0.1, dur: 0.18, freq: 350, type: 'lowpass', delay: 0.01 });
  }

  pass() {
    this._tone({ type: 'sine', freq: 190, freqEnd: 90, gain: 0.14, dur: 0.1 });
    this._noiseHit({ gain: 0.05, dur: 0.05, freq: 2400 });
  }

  shot(power = 1, perfect = false) {
    this.kick(power);
    this._noiseHit({ gain: 0.13, dur: 0.24, freq: 1100, type: 'bandpass', q: 0.7 });
    if (perfect) this.perfect();
  }

  perfect() {
    this._tone({ type: 'triangle', freq: 1046, gain: 0.15, dur: 0.32, delay: 0.02 });
    this._tone({ type: 'triangle', freq: 1568, gain: 0.11, dur: 0.38, delay: 0.1 });
    this._tone({ type: 'sine', freq: 2093, gain: 0.06, dur: 0.4, delay: 0.18 });
  }

  save() {
    this._noiseHit({ gain: 0.3, dur: 0.22, freq: 600, type: 'lowpass' });
    this._tone({ type: 'sine', freq: 240, freqEnd: 80, gain: 0.2, dur: 0.18 });
  }

  post() {
    this._tone({ type: 'triangle', freq: 1170, freqEnd: 980, gain: 0.26, dur: 0.55 });
    this._tone({ type: 'sine', freq: 2350, freqEnd: 1900, gain: 0.09, dur: 0.38 });
    this._noiseHit({ gain: 0.08, dur: 0.08, freq: 3000 });
  }

  tackle() {
    this._noiseHit({ gain: 0.26, dur: 0.24, freq: 300, type: 'lowpass' });
    this._tone({ type: 'sine', freq: 130, freqEnd: 52, gain: 0.17, dur: 0.22 });
  }

  whistle() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    const lfo = this.ctx.createOscillator();
    const lfoGain = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.value = 2250;
    lfo.frequency.value = 26;
    lfoGain.gain.value = 65;
    lfo.connect(lfoGain);
    lfoGain.connect(osc.frequency);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.18, t + 0.02);
    g.gain.setValueAtTime(0.18, t + 0.28);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.55);
    osc.connect(g);
    g.connect(this.master);
    osc.start(t);
    lfo.start(t);
    osc.stop(t + 0.6);
    lfo.stop(t + 0.6);
    this._tone({ type: 'sine', freq: 2680, gain: 0.06, dur: 0.4 });
  }

  goal() {
    this._crowdCheer(1);
    const notes = [220, 277.18, 329.63, 440];
    notes.forEach((f, i) => {
      this._tone({ type: 'triangle', freq: f, gain: 0.08, dur: 0.9, delay: i * 0.05, attack: 0.03 });
      this._tone({ type: 'sawtooth', freq: f / 2, gain: 0.03, dur: 0.7, delay: i * 0.05 });
    });
    this._noiseHit({ gain: 0.22, dur: 1.4, freq: 900, type: 'bandpass', q: 0.4 });
  }

  _crowdCheer(level = 0.8) {
    if (!this.crowdGain) return;
    const t = this.ctx.currentTime;
    this.crowdGain.gain.cancelScheduledValues(t);
    this.crowdGain.gain.setValueAtTime(this.crowdGain.gain.value, t);
    this.crowdGain.gain.linearRampToValueAtTime(0.02 + 0.17 * level, t + 0.18);
    this.crowdGain.gain.exponentialRampToValueAtTime(0.045, t + 2.8);
  }

  saveCheer() {
    this._crowdCheer(0.35);
  }

  ui() {
    this._tone({ type: 'sine', freq: 660, freqEnd: 880, gain: 0.055, dur: 0.08 });
  }

  select() {
    this._tone({ type: 'triangle', freq: 440, freqEnd: 660, gain: 0.06, dur: 0.11 });
    this._tone({ type: 'sine', freq: 990, gain: 0.03, dur: 0.12, delay: 0.03 });
  }
}

