    if (player.tackleCooldown > 0 || player.slideTimer > 0) return;
    let dx = axes.x;
    let dz = axes.y;
    if (Math.hypot(dx, dz) < 0.2) {
      dx = Math.sin(player.facing);
      dz = Math.cos(player.facing);
