426:     this.ball.update(dt * 0.55);
427:     // keep the ball inside the net
428:     const dir = Math.sign(this.goalZ || 1);
429:     const maxZ = FIELD.halfLength + FIELD.goalDepth - 0.45;
430:     if (Math.abs(this.ball.pos.z) > maxZ) {
431:       this.ball.pos.z = Math.sign(this.ball.pos.z) * maxZ;
432:       this.ball.vel.z *= -0.35;
433:       this.ball.vel.x *= 0.7;
434:       this.ball.vel.y *= 0.5;
435:     }
436:     this.ball.pos.x = clamp(this.ball.pos.x, -FIELD.goalWidth / 2 + 0.3, FIELD.goalWidth / 2 - 0.3);
437: 
438:     for (const p of this.players) {
439:       if (p === this.controlled) continue;
440:       p.update(dt * 0.7, 0, 0, false, 0);
441:     }
442:     if (this.controlled) this.controlled.update(dt * 0.7, 0, 0, false, 0);
443: 
444:     if (this.goalTimer <= 0) {
445:       if (this.pendingEnd) {
446:         this.endMatch(this.golden ? 'GOLDEN GOAL' : 'FULL TIME');
447:       } else {
448:         this.resetForKickoff(this.concededTeam || 'home');
449:         this.audio?.whistle?.();
450:         this.ui?.toast?.('KICK OFF', '');
451:       }
452:     }
453:   }
