513:   // ============================ HUMAN INPUT ============================
514:   handleHumanInput(dt) {
515:     if (!this.controlled) return;
516:     const axes = this.input.moveAxes();
517:     const shootPressed = this.input.wasPressed('shoot');
518:     const shootReleased = this.input.wasReleased('shoot');
519: 
520:     if (shootPressed) {
521:       if (this.owner && this.owner.team.id === 'home' && !this.owner.isKeeper) {
522:         this.startCharge(this.owner);
523:       } else if (!this.owner) {
524:         const near = horizDist(this.ball.pos, this.controlled.pos) < 2.2 && this.ball.pos.y < 2.5;
525:         if (near) this.volley(this.controlled, axes);
526:       }
527:     }
528: 
529:     if (this.charging) {
530:       if (!this.owner || this.owner !== this.chargeOwner || this.owner.team.id !== 'home') {
531:         this.cancelCharge();
532:       } else {
533:         this.chargeTime += dt;
534:         const ratio = Math.min(1, this.chargeTime / BASE.shotCharge);
535:         this.chargeOwner.charge = ratio;
536:         const perfect = ratio >= this.perfectMin() && ratio <= this.perfectMax();
537:         this.ui?.setCharge?.(ratio, perfect, true);
538:         if (shootReleased) {
539:           const owner = this.chargeOwner;
540:           this.shoot(owner, ratio, perfect, false, axes);
541:           this.cancelCharge(false);
542:         }
543:       }
544:     }
545: 
546:     if (this.input.wasPressed('pass')) {
547:       if (this.charging) this.cancelCharge();
548:       if (this.owner && this.owner.team.id === 'home' && !this.owner.isKeeper) {
549:         this.passBall(this.owner, this.input.isDown('sprint'), axes);
550:       } else {
551:         this.switchToNextDefender();
552:       }
553:     }
554: 
555:     if (this.input.wasPressed('skill')) {
556:       if (this.charging) this.cancelCharge();
557:       if (this.owner && this.owner.team.id === 'home' && !this.owner.isKeeper) {
558:         this.skillMove(this.owner, axes);
559:       } else if (this.controlled) {
560:         this.slideTackle(this.controlled, axes);
561:       }
562:     }
563:   }
