591:   computeShot(player, ratio, axes = null, aiOpts = null) {
592:     const goalZ = player.team.dir * FIELD.halfLength;
593:     const aimInput = aiOpts?.aimX != null ? aiOpts.aimX : clamp(axes?.x ?? 0, -1, 1);
594:     let targetX = aimInput * (FIELD.goalWidth / 2 - 0.75) - player.pos.x * 0.17;
595:     if (Math.abs(aimInput) < 0.12) targetX -= player.pos.x * 0.12;
596:     targetX = clamp(targetX, -FIELD.goalWidth / 2 + 0.5, FIELD.goalWidth / 2 - 0.5);
597:     let targetY = clamp(0.36 + ratio * 2.1 + (aiOpts?.liftY ?? 0), 0.36, FIELD.goalHeight - 0.22);
598:     if (ratio < 0.2) targetY = 0.42;
599: 
600:     const dx = targetX - this.ball.pos.x;
601:     const dz = goalZ - this.ball.pos.z;
602:     const dist = Math.hypot(dx, dz);
603:     const perfect = aiOpts?.perfect ?? false;
604:     let speed = (22.5 + 13.5 * ratio) * player.stats.shotPower;
605:     if (perfect) speed *= 1.14;
606:     if (aiOpts) speed *= 0.94 + (aiOpts.skill ?? 0.75) * 0.14;
607:     const t = Math.max(0.12, dist / speed);
608:     let lift = (targetY - this.ball.pos.y) / t + 0.5 * BASE.gravity * t;
609:     lift = clamp(lift, 0.4, 10.5);
610: 
611:     let angle = Math.atan2(dx, dz);
612:     let spread = (0.024 + (1 - ratio) * 0.02) / Math.max(0.8, player.stats.shotAccuracy);
613:     if (perfect) spread *= 0.3;
614:     if (aiOpts) spread *= Math.max(0.35, 1.85 - (aiOpts.skill ?? 0.75) * 1.35);
615:     angle += (Math.random() - 0.5) * spread;
616:     lift += (Math.random() - 0.5) * spread * 10;
617: 
618:     const spin = Math.sign(targetX - this.ball.pos.x || 1) * (4.2 + ratio * 5.2) * player.stats.curve * (perfect ? 1.14 : 1);
619:     return {
620:       dir: new THREE.Vector3(Math.sin(angle), 0, Math.cos(angle)),
621:       speed,
622:       lift,
623:       spin,
624:       targetX,
625:       targetY,
626:       goalZ,
627:       perfect,
628:     };
629:   }
630: 
631:   shoot(player, ratio, perfect = false, ai = false, axes = null, aiOpts = null) {
632:     if (!player) return;
633:     const opts = ai ? { ...(aiOpts || {}), skill: this.difficulty.shotSkill, perfect } : null;
634:     const shot = this.computeShot(player, ratio, axes, opts);
635:     shot.perfect = perfect;
636: 
637:     if (this.owner === player) {
638:       player.setOwner(false);
639:       this.owner = null;
640:     }
641:     this.ball.kick(shot.dir, shot.speed, shot.lift, shot.spin);
642:     this.ball.lastKicker = player;
643:     this.lastTouch = player;
644:     this.ball.passTarget = null;
645:     player.play('kick', 0.24);
646:     player.charge = 0;
647:     player.kickCooldown = 0.22;
648:     this.effects.kickBurst(this.ball.pos, player.team.color, 0.6 + ratio * 0.8);
649:     this.audio?.shot?.(ratio, perfect);
650:     this.shake = Math.max(this.shake, 0.14 + ratio * 0.22);
651:     if (player.team.id === 'home') this.stats.shots += 1;
652:     if (perfect && !ai) {
653:       this.hitStop = 0.09;
654:       this.ui?.toast?.('PERFECT STRIKE', '');
655:       this.audio?.perfect?.();
656:     }
657:     if (ai && ratio > 0.8) this.audio?.kick?.(ratio);
658:     this.controlLock = Math.max(this.controlLock, 0.25);
659:   }
