661:   volley(player, axes) {
662:     const shot = this.computeShot(player, 0.78, axes, { skill: 0.85 });
663:     shot.lift += 1.2;
664:     this.ball.kick(shot.dir, shot.speed * 0.94, shot.lift, shot.spin * 0.7);
665:     this.ball.lastKicker = player;
666:     this.lastTouch = player;
667:     this.ball.passTarget = null;
668:     player.play('kick', 0.22);
669:     this.effects.kickBurst(this.ball.pos, player.team.color, 1.2);
670:     this.audio?.shot?.(0.8, false);
671:     this.shake = Math.max(this.shake, 0.2);
672:     if (player.team.id === 'home') {
673:       this.stats.shots += 1;
674:       this.ui?.toast?.('VOLLEY!', '');
675:     }
676:   }
