678:   findPassTarget(player, axes = null, lofted = false) {
679:     let aimX;
680:     let aimZ;
681:     if (axes && Math.hypot(axes.x, axes.y) > 0.3) {
682:       const l = Math.hypot(axes.x, axes.y);
683:       aimX = axes.x / l;
684:       aimZ = axes.y / l;
685:     } else {
686:       aimX = Math.sin(player.facing);
687:       aimZ = Math.cos(player.facing);
688:     }
689:     const goalZ = player.team.dir * FIELD.halfLength;
690:     let best = null;
691:     let bestScore = -Infinity;
692:     for (const t of this.players) {
693:       if (t === player || t.team.id !== player.team.id || t.isKeeper) continue;
694:       const dx = t.pos.x - player.pos.x;
695:       const dz = t.pos.z - player.pos.z;
696:       const dist = Math.hypot(dx, dz);
697:       if (dist < 1.5) continue;
698:       const nx = dx / dist;
699:       const nz = dz / dist;
700:       const dot = nx * aimX + nz * aimZ;
701:       let score = dot * 1.7 - dist * 0.025;
702:       score += ((t.pos.z - player.pos.z) * player.team.dir) * 0.065;
703:       score += (t.pos.z * player.team.dir) * 0.012;
704:       // lane clearance
705:       let lanePenalty = 0;
706:       for (const o of this.players) {
707:         if (o.team.id === player.team.id || o.isKeeper) continue;
708:         const t2 = ((o.pos.x - player.pos.x) * dx + (o.pos.z - player.pos.z) * dz) / (dist * dist);
709:         if (t2 < 0.04 || t2 > 0.98) continue;
710:         const px = player.pos.x + dx * t2;
711:         const pz = player.pos.z + dz * t2;
712:         const off = Math.hypot(o.pos.x - px, o.pos.z - pz);
713:         if (off < 0.85) lanePenalty += 1.1;
714:         else if (off < 1.65) lanePenalty += 0.45;
715:       }
716:       score -= lanePenalty;
717:       let space = 99;
718:       for (const o of this.players) {
719:         if (o.team.id === player.team.id) continue;
720:         if (o.isKeeper) continue;
721:         space = Math.min(space, horizDist(o.pos, t.pos));
722:       }
723:       if (space > 5) score += 0.6;
724:       else if (space < 2.5) score -= 0.45;
725:       if (dist > 25) score -= 0.6;
726:       if (lofted) score += (t.pos.z - player.pos.z) * player.team.dir * 0.02;
727:       if (score > bestScore) {
728:         bestScore = score;
729:         best = t;
730:       }
731:     }
732:     return best;
733:   }
734: 
735:   passBall(player, lofted = false, axes = null) {
736:     if (!player) return null;
737:     const target = this.findPassTarget(player, axes, lofted);
738:     player.play('kick', 0.2);
739:     this.audio?.pass?.();
740:     if (!target) {
741:       const dir = new THREE.Vector3(Math.sin(player.facing), 0, Math.cos(player.facing));
742:       this.ball.kick(dir, 19, lofted ? 5.5 : 0.6, 0);
743:       this.ball.lastKicker = player;
744:       this.lastTouch = player;
745:       if (this.owner === player) {
746:         player.setOwner(false);
747:         this.owner = null;
748:       }
749:       this.effects.kickBurst(this.ball.pos, player.team.color, 0.4);
750:       return null;
751:     }
752:     const lead = lofted ? 4.2 : 1.0;
753:     const tx = target.pos.x + target.vel.x * 0.25;
754:     const tz = target.pos.z + target.vel.z * 0.25 + player.team.dir * lead;
755:     const dx = tx - this.ball.pos.x;
756:     const dz = tz - this.ball.pos.z;
757:     const dist = Math.max(1, Math.hypot(dx, dz));
758:     let angle = Math.atan2(dx, dz);
759:     angle += (Math.random() - 0.5) * (0.028 / Math.max(0.9, player.stats.control));
760:     if (lofted) angle = Math.atan2(dx, dz);
761:     const dir = new THREE.Vector3(Math.sin(angle), 0, Math.cos(angle));
762:     const speed = lofted ? clamp(11 + dist * 0.62, 13, 23) : clamp(8 + dist * 1.08, 12, 25);
763:     const lift = lofted ? clamp(3.6 + dist * 0.11, 4, 8.5) : 0.35;
764:     const spin = lofted ? 0 : (Math.random() - 0.5) * 1.6;
765: 
766:     if (this.owner === player) {
767:       player.setOwner(false);
768:       this.owner = null;
769:     }
770:     this.ball.kick(dir, speed, lift, spin);
771:     this.ball.lastKicker = player;
772:     this.ball.lastPass = player;
773:     this.ball.passTarget = target;
774:     this.ball.passTeam = player.team.id;
775:     this.ball.passTimer = 1.6;
776:     this.lastTouch = player;
777:     this.effects.kickBurst(this.ball.pos, player.team.color, 0.25);
778:     this.aiPassTarget = target;
779:     if (player.team.id === 'home') {
780:       this.stats.passes += 1;
781:       this.setControlled(target);
782:       this.controlLock = 0.85;
783:       this.lastPassTarget = target;
784:       target.targetRing.visible = true;
785:       target.targetRing.material.color.setHex(0x44f3ff);
786:     }
787:     this.controlLock = Math.max(this.controlLock, 0.6);
788:     return target;
789:   }
