823:   buildAimGuide() {
824:     const geo = new THREE.BufferGeometry();
825:     const positions = new Float32Array(20 * 3);
826:     geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
827:     this.aimLine = new THREE.Line(
828:       geo,
829:       new THREE.LineBasicMaterial({ color: this.playstyle.color, transparent: true, opacity: 0.5, depthWrite: false, blending: THREE.AdditiveBlending })
830:     );
831:     this.aimLine.frustumCulled = false;
832:     this.aimLine.visible = false;
833:     this.scene.add(this.aimLine);
834: 
835:     this.aimRing = new THREE.Mesh(
836:       new THREE.RingGeometry(0.5, 0.64, 40),
837:       new THREE.MeshBasicMaterial({ color: this.playstyle.color, transparent: true, opacity: 0.85, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending })
838:     );
839:     this.aimRing.rotation.x = -Math.PI / 2;
840:     this.aimRing.visible = false;
841:     this.scene.add(this.aimRing);
