844:   updateAimGuide() {
845:     if (!this.aimLine) return;
846:     if (!this.charging || !this.owner || !this.chargeOwner) {
847:       this.aimLine.visible = false;
848:       this.aimRing.visible = false;
849:       return;
850:     }
851:     const axes = this.input.moveAxes();
852:     const ratio = Math.min(1, this.chargeTime / BASE.shotCharge);
853:     const shot = this.computeShot(this.chargeOwner, ratio, axes);
854:     const positions = this.aimLine.geometry.attributes.position.array;
855:     const n = 20;
856:     for (let i = 0; i < n; i++) {
857:       const t = i / (n - 1);
858:       const x = lerp(this.ball.pos.x, shot.targetX, t) + Math.sin(t * Math.PI) * shot.spin * 0.045;
859:       const z = lerp(this.ball.pos.z, shot.goalZ, t);
860:       positions[i * 3] = x;
861:       positions[i * 3 + 1] = 0.045;
862:       positions[i * 3 + 2] = z;
863:     }
864:     this.aimLine.geometry.attributes.position.needsUpdate = true;
865:     this.aimLine.visible = true;
866:     this.aimLine.material.color.setHex(this.playstyle.color);
867:     this.aimLine.material.opacity = 0.3 + ratio * 0.35;
868:     this.aimRing.visible = true;
869:     this.aimRing.position.set(shot.targetX, 0.05, shot.goalZ - this.chargeOwner.team.dir * 0.18);
870:     const pulse = 1 + Math.sin(this.now * 8) * 0.08;
871:     this.aimRing.scale.setScalar(pulse * (0.8 + ratio * 0.4));
872:     this.aimRing.material.color.setHex(this.playstyle.color);
873:   }
