897:   // ============================ PHYSICS & CONTACT ============================
898:   updatePlayerPhysics(dt) {
899:     const diffSpeed = this.difficulty.aiSpeed;
900:     for (const p of this.players) {
901:       if (p === this.controlled) {
902:         const axes = this.input.moveAxes();
903:         p.update(dt, axes.x, axes.y, this.input.isDown('sprint'), 1);
904:       } else if (p.isKeeper) {
905:         p.update(dt, p.intent.x, p.intent.y, p.aiSprint, p.aiSpeedMul);
906:       } else {
907:         p.update(dt, p.intent.x, p.intent.y, p.aiSprint, p.aiSpeedMul * (p.team.id === 'away' ? diffSpeed : 1));
908:       }
909:       p.updateDive(dt);
910:       const margin = 0.55;
911:       p.pos.x = clamp(p.pos.x, -FIELD.halfWidth + margin, FIELD.halfWidth - margin);
912:       p.pos.z = clamp(p.pos.z, -FIELD.halfLength + margin, FIELD.halfLength - margin);
913:       p.root.position.set(p.pos.x, 0, p.pos.z);
914:       p.root.rotation.y = p.facing;
915:       p.contest = Math.max(0, (p.contest || 0) - dt * 0.6);
916:     }
917:   }
