919:   collidePlayers() {
920:     const list = this.players;
921:     for (let i = 0; i < list.length; i++) {
922:       for (let j = i + 1; j < list.length; j++) {
923:         const a = list[i];
924:         const b = list[j];
925:         if (a.isKeeper && b.isKeeper) continue;
926:         const dx = b.pos.x - a.pos.x;
927:         const dz = b.pos.z - a.pos.z;
928:         let d = Math.hypot(dx, dz);
929:         if (d >= 1.16 || d < 0.0001) continue;
930:         const overlap = 1.16 - d;
931:         const nx = dx / d;
932:         const nz = dz / d;
933:         const aSlide = a.slideTimer > 0;
934:         const bSlide = b.slideTimer > 0;
935:         let aShare = 0.5;
936:         let bShare = 0.5;
937:         if (a.isKeeper) { aShare = 0; bShare = 1; }
938:         else if (b.isKeeper) { aShare = 1; bShare = 0; }
939:         else if (aSlide !== bSlide) {
940:           if (aSlide) { aShare = 0.15; bShare = 0.85; }
941:           else { aShare = 0.85; bShare = 0.15; }
942:         }
943:         a.pos.x -= nx * overlap * aShare;
944:         a.pos.z -= nz * overlap * aShare;
945:         b.pos.x += nx * overlap * bShare;
946:         b.pos.z += nz * overlap * bShare;
947:         a.root.position.set(a.pos.x, 0, a.pos.z);
948:         b.root.position.set(b.pos.x, 0, b.pos.z);
949:         if (aSlide && !b.isKeeper) {
950:           b.vel.x += nx * 2.6;
951:           b.vel.z += nz * 2.6;
952:         }
953:         if (bSlide && !a.isKeeper) {
954:           a.vel.x -= nx * 2.6;
955:           a.vel.z -= nz * 2.6;
956:         }
957:       }
958:     }
959:   }
