974:   updateDribble(dt) {
975:     const o = this.owner;
976:     if (!o) return;
977:     if (o.isKeeper) {
978:       const fx = Math.sin(o.facing);
979:       const fz = Math.cos(o.facing);
980:       this.ball.pos.set(o.pos.x + fx * 0.52, 1.05, o.pos.z + fz * 0.52);
981:       this.ball.vel.set(o.vel.x * 0.4, 0, o.vel.z * 0.4);
982:       return;
983:     }
984:     const speed = Math.hypot(o.vel.x, o.vel.z);
985:     let offset = 0.66 + Math.min(speed, 12.5) * 0.045;
986:     if (o.sprinting) offset += 0.34;
987:     if (o.skillTimer > 0) offset += 0.5;
988:     if (o.charge > 0.03) offset -= 0.08;
989:     const fx = Math.sin(o.facing);
990:     const fz = Math.cos(o.facing);
991:     let tx = o.pos.x + fx * offset + o.vel.x * 0.035;
992:     let tz = o.pos.z + fz * offset + o.vel.z * 0.035;
993:     tx += Math.cos(o.runPhase) * 0.045;
994:     tz -= Math.sin(o.runPhase) * 0.045;
995:     tx = clamp(tx, -FIELD.halfWidth + 0.45, FIELD.halfWidth - 0.45);
996:     tz = clamp(tz, -FIELD.halfLength + 0.5, FIELD.halfLength - 0.5);
997:     const rate = (o.sprinting ? 10.5 : 17.5) * (0.86 + o.stats.control * 0.2);
998:     const oldX = this.ball.pos.x;
999:     const oldZ = this.ball.pos.z;
1000:     this.ball.pos.x = damp(oldX, tx, rate, dt);
1001:     this.ball.pos.z = damp(oldZ, tz, rate, dt);
1002:     this.ball.pos.y = damp(this.ball.pos.y, this.ball.radius + (o.skillTimer > 0 ? 0.05 : 0), 14, dt);
1003:     if (dt > 0) this.ball.vel.set((this.ball.pos.x - oldX) / dt, 0, (this.ball.pos.z - oldZ) / dt);
1004:   }
