1006:   ballBodyCollisions() {
1007:     const speed = this.ball.vel.length();
1008:     if (speed < 19 || this.ball.pickupLock > 0) return;
1009:     for (const p of this.players) {
1010:       if (p.isKeeper) continue;
1011:       if (this.ball.pos.y > 1.85) continue;
1012:       const dx = this.ball.pos.x - p.pos.x;
1013:       const dz = this.ball.pos.z - p.pos.z;
1014:       const d = Math.hypot(dx, dz);
1015:       if (d > 0.72 || d < 0.001) continue;
1016:       const nx = dx / d;
1017:       const nz = dz / d;
1018:       const dot = this.ball.vel.x * nx + this.ball.vel.z * nz;
1019:       if (dot >= 0) continue;
1020:       this.ball.vel.x -= 1.7 * dot * nx;
1021:       this.ball.vel.z -= 1.7 * dot * nz;
1022:       this.ball.vel.multiplyScalar(0.52);
1023:       this.ball.vel.y = Math.max(this.ball.vel.y, 2.1);
1024:       this.ball.spin *= 0.4;
1025:       this.ball.pickupLock = 0.16;
1026:       this.ball.lastKicker = p;
1027:       this.lastTouch = p;
1028:       this.ball.passTarget = null;
1029:       this.effects.burst(this.ball.pos, 9, p.team.color, 3.2, { life: 0.32, gravity: 4 });
1030:       this.audio?.block?.();
1031:       this.shake = Math.max(this.shake, 0.09);
1032:       return;
1033:     }
1034:   }
