1036:   resolvePossession(dt = 0.016) {
1037:     if (this.owner) {
1038:       const owner = this.owner;
1039:       if (this.kickoffTimer <= 0 && !owner.isKeeper) {
1040:         if (horizDist(this.ball.pos, owner.pos) > 2.6) {
1041:           this.loseOwnership();
1042:         } else {
1043:           for (const o of this.players) {
1044:             if (o.team.id === owner.team.id || o.isKeeper) continue;
1045:             const d = horizDist(o.pos, owner.pos);
1046:             if (d > 1.9) {
1047:               o.contest = 0;
1048:               continue;
1049:             }
1050:             if (d < 1.82 && o.slideTimer > 0) {
1051:               this.stealBall(o, owner, true);
1052:               return;
1053:             }
1054:             const pressing = o.sprinting || d < 1.05;
1055:             if (!pressing || d > 1.16) continue;
1056:             o.contest = (o.contest || 0) + dt;
1057:             if (o.contest > 0.4) {
1058:               o.contest = 0;
1059:               const chance = clamp(0.36 * (o.stats.strength / owner.stats.strength), 0.12, 0.72);
1060:               if (Math.random() < chance) {
1061:                 this.stealBall(o, owner, false);
1062:                 return;
1063:               }
1064:             }
1065:           }
1066:         }
1067:       }
1068:     }
1069:     if (!this.owner) this.tryPickup(dt);
1070:   }
