1079:   stealBall(winner, owner, slide = false) {
1080:     if (!winner || !owner || winner.team.id === owner.team.id) return;
1081:     owner.setOwner(false);
1082:     this.ball.owner = null;
1083:     this.owner = null;
1084:     this.ball.passTarget = null;
1085:     const fx = Math.sin(winner.facing);
1086:     const fz = Math.cos(winner.facing);
1087:     if (slide) {
1088:       this.ball.vel.set(fx * 6.8 + (Math.random() - 0.5) * 2, 1.2, fz * 6.8 + (Math.random() - 0.5) * 2);
1089:       this.ball.spin = 0;
1090:       this.ball.pickupLock = 0.18;
1091:     } else {
1092:       this.giveBall(winner);
1093:     }
1094:     owner.vel.x -= fx * 2.2;
1095:     owner.vel.z -= fz * 2.2;
1096:     this.ball.lastKicker = winner;
1097:     this.lastTouch = winner;
1098:     this.effects.ring(winner.pos, winner.team.color, 3);
1099:     this.effects.burst(new THREE.Vector3(owner.pos.x, 0.6, owner.pos.z), 12, 0xffffff, 4, { life: 0.35 });
1100:     this.audio?.tackle?.();
1101:     this.shake = Math.max(this.shake, 0.24);
1102:     if (winner.team.id === 'home') this.stats.tackles += 1;
1103:     winner.contest = 0;
1104:     this.controlLock = Math.max(this.controlLock, 0.3);
1105:   }
