1107:   tryPickup(dt) {
1108:     if (this.ball.pickupLock > 0 || this.owner) return;
1109:     const speed = this.ball.vel.length();
1110:     if (this.ball.pos.y > 1.7) return;
1111:     let best = null;
1112:     let bestD = Infinity;
1113:     for (const p of this.players) {
1114:       if (p.isKeeper) continue;
1115:       const d = horizDist(p.pos, this.ball.pos);
1116:       const isPass = this.ball.passTarget === p && this.ball.passTeam === p.team.id;
1117:       let reach = 0.82 + (p.stats.control - 1) * 0.32;
1118:       if (p.slideTimer > 0) reach = 1.42;
1119:       if (isPass) reach += 0.32;
1120:       const maxSpeed = p.slideTimer > 0 ? 17 : isPass ? 31 : 21;
1121:       if (speed > maxSpeed) continue;
1122:       if (d < reach && d < bestD) {
1123:         bestD = d;
1124:         best = p;
1125:       }
1126:     }
1127:     if (!best) return;
1128:     if (this.ball.passTarget === best) {
1129:       this.lastPassTarget = best;
1130:       if (best.team.id === 'home') this.ui?.setHint?.('');
1131:     }
1132:     this.giveBall(best);
1133:     this.ball.passTarget = null;
1134:     this.ball.lastKicker = best;
1135:     this.lastTouch = best;
1136:     this.audio?.touch?.();
1137:     if (best.team.id === 'home' && !best.isKeeper) this.setControlled(best);
1138:   }
