1140:   updateControlSwitch() {
1141:     if (this.controlLock > 0) return;
1142:     if (this.controlled && (this.controlled.slideTimer > 0 || this.charging)) return;
1143:     if (this.owner && this.owner.team.id === 'home' && !this.owner.isKeeper) {
1144:       if (this.controlled !== this.owner) this.setControlled(this.owner);
1145:       return;
1146:     }
1147:     this.switchTimer -= 0.016;
1148:     if (this.switchTimer > 0) return;
1149:     this.switchTimer = 0.18;
1150:     const candidate = this.nearestHomeToBall();
1151:     if (!candidate) return;
1152:     if (!this.controlled) {
1153:       this.setControlled(candidate);
1154:       return;
1155:     }
1156:     const currentD = horizDist(this.controlled.pos, this.ball.pos);
1157:     const candidateD = horizDist(candidate.pos, this.ball.pos);
1158:     if (candidate !== this.controlled && candidateD + 1.1 < currentD) {
1159:       this.setControlled(candidate);
1160:     }
1161:   }
