1183:   checkPosts() {
1184:     if ((this.postCd || 0) > 0) return;
1185:     const b = this.ball.pos;
1186:     const r = this.ball.radius;
1187:     const hw = FIELD.goalWidth / 2;
1188:     for (const z of [-FIELD.halfLength, FIELD.halfLength]) {
1189:       for (const x of [-hw, hw]) {
1190:         const dx = b.x - x;
1191:         const dz = b.z - z;
1192:         const d = Math.hypot(dx, dz);
1193:         if (d < r + 0.12 && b.y < FIELD.goalHeight + 0.1 && d > 0.001) {
1194:           const nx = dx / d;
1195:           const nz = dz / d;
1196:           const dot = this.ball.vel.x * nx + this.ball.vel.z * nz;
1197:           if (dot < 0) {
1198:             this.ball.vel.x -= 1.7 * dot * nx;
1199:             this.ball.vel.z -= 1.7 * dot * nz;
1200:             this.ball.vel.multiplyScalar(0.66);
1201:             this.ball.vel.y = Math.max(this.ball.vel.y, 1.4);
1202:             this.postCd = 0.4;
1203:             this.ball.pickupLock = 0.1;
