1207:             if (this.ball.shotActive && this.lastKicker?.team.id === 'home') this.ui?.toast?.('OFF THE POST', 'bad');
1208:             this.ball.shotActive = false;
1209:             return;
1210:           }
1211:         }
1212:       }
1213:     }
1214:     // crossbar
1215:     if (Math.abs(b.z) > FIELD.halfLength - 0.3 && Math.abs(b.x) < hw + 0.1) {
1216:       if (Math.abs(b.y - FIELD.goalHeight) < r + 0.06 && this.ball.vel.y > -1) {
1217:         this.ball.vel.y = -Math.abs(this.ball.vel.y) * 0.52 - 0.4;
1218:         this.ball.vel.z *= 0.6;
1219:         this.ball.vel.x *= 0.8;
1220:         this.postCd = 0.35;
1221:         this.audio?.post?.();
1222:         this.shake = Math.max(this.shake, 0.36);
1223:         if (this.ball.shotActive && this.lastKicker?.team.id === 'home') this.ui?.toast?.('CROSSBAR!', 'bad');
