1242:     const concedingId = teamId === 'home' ? 'away' : 'home';
1243:     this.score[teamId] += 1;
1244:     this.goalTeam = teamId;
1245:     this.concededTeam = concedingId;
1246:     this.goalZ = scoring.dir * FIELD.halfLength;
1247:     const last = this.lastTouch;
1248:     const ownGoal = !!(last && last.team.id !== teamId);
1249:     const scorerName = last ? `${last.name}${ownGoal ? ' · OG' : ''}` : scoring.name;
1250:     this.goalScorer = scorerName;
