1252:     this.cancelCharge(false);
1253:     this.charging = false;
1254:     if (this.owner) {
1255:       this.owner.setOwner(false);
1256:       this.owner = null;
1257:     }
1258:     this.ball.owner = null;
1259:     if (this.controlled) this.controlled.setControlled(false);
1260:     this.controlled = null;
1261:     for (const p of this.players) {
1262:       p.setOwner(false);
1263:       p.setControlled(false);
1264:       p.charge = 0;
1265:       p.contest = 0;
1266:       if (p.team.id === teamId) p.celebrateFor(2.5);
1267:       else p.play('dejected', 2.5);
