1271:     this.goalTimer = MATCH.goalCelebration;
1272:     this.orbitTime = 0;
1273:     this.pendingEnd = this.score[teamId] >= MATCH.goalsToWin || this.golden;
1274:     this.effects.confetti(new THREE.Vector3(0, 1.6, this.goalZ - Math.sign(this.goalZ) * 1.2), [scoring.color, 0xd7ff4a, 0xffffff, TEAMS[concedingId].color]);
1275:     this.effects.ring(new THREE.Vector3(this.ball.pos.x, 0.1, this.ball.pos.z), scoring.color, 5);
1276:     this.audio?.goal?.();
1277:     this.shake = Math.max(this.shake, 0.5);
1278:     this.ui?.flashScreen?.();
1279:     this.ui?.showGoal?.({ teamId, teamName: scoring.name, scorer: scorerName, ownGoal, score: { ...this.score } });
