1283:   ballBoundaries() {
1284:     const b = this.ball.pos;
1285:     const r = this.ball.radius;
1286:     const hw = FIELD.halfWidth;
1287:     const hl = FIELD.halfLength;
1288:     let hit = 0;
1289:     if (b.x > hw - r) {
1290:       b.x = hw - r;
1291:       if (this.ball.vel.x > 0) this.ball.vel.x *= -0.68;
1292:       hit = 1;
1293:     } else if (b.x < -hw + r) {
1294:       b.x = -hw + r;
1295:       if (this.ball.vel.x < 0) this.ball.vel.x *= -0.68;
1296:       hit = 1;
1297:     }
1298:     const inMouth = Math.abs(b.x) < FIELD.goalWidth / 2 - 0.02;
1299:     const underBar = b.y < FIELD.goalHeight - 0.02;
1300:     if (!inMouth || !underBar) {
1301:       if (b.z > hl - r) {
1302:         b.z = hl - r;
1303:         if (this.ball.vel.z > 0) this.ball.vel.z *= -0.62;
1304:         hit = 1;
1305:       } else if (b.z < -hl + r) {
1306:         b.z = -hl + r;
1307:         if (this.ball.vel.z < 0) this.ball.vel.z *= -0.62;
1308:         hit = 1;
1309:       }
1310:     } else {
1311:       b.z = clamp(b.z, -hl - FIELD.goalDepth + 0.35, hl + FIELD.goalDepth - 0.35);
1312:     }
1313:     if (hit) {
1314:       this.ball.spin *= 0.5;
1315:       if (this.wallSoundCd <= 0) {
1316:         this.wallSoundCd = 0.16;
1317:         this.audio?.wall?.();
1318:       }
1319:       if (Math.hypot(this.ball.vel.x, this.ball.vel.z) > 8) {
1320:         this.effects.burst(new THREE.Vector3(b.x, Math.max(0.3, b.y), b.z), 5, 0x9adfff, 2, { life: 0.25 });
1321:       }
1322:     }
1323:   }
