1366:   applyCamera(desiredPos, desiredLook, dt, fovTarget, lambda = 5) {
1367:     const k = 1 - Math.exp(-lambda * dt);
1368:     this.camPos.lerp(desiredPos, k);
1369:     this.camLook.lerp(desiredLook, k);
1370:     this.camera.position.copy(this.camPos);
1371:     if (this.shake > 0) {
1372:       const s = this.shake * 0.35;
1373:       this.camera.position.x += (Math.random() - 0.5) * s;
1374:       this.camera.position.y += (Math.random() - 0.5) * s;
1375:       this.camera.position.z += (Math.random() - 0.5) * s * 0.5;
1376:     }
1377:     this.camera.lookAt(this.camLook);
1378:     this.camera.fov = damp(this.camera.fov, fovTarget, 4, dt);
1379:     this.camera.updateProjectionMatrix();
