1382:   updateCamera(dt) {
1383:     const el = this.renderer.domElement;
1384:     const aspect = el.clientWidth / Math.max(1, el.clientHeight);
1385:     const portrait = aspect < 0.95;
1386:     const focus = this.cameraFocus();
