265: function createSky(scene) {
266:   const geo = new THREE.SphereGeometry(160, 32, 20);
267:   const mat = new THREE.ShaderMaterial({
268:     side: THREE.BackSide,
269:     depthWrite: false,
270:     fog: false,
271:     uniforms: {
272:       top: { value: new THREE.Color(0x010309) },
273:       mid: { value: new THREE.Color(0x071527) },
274:       bottom: { value: new THREE.Color(0x02050b) },
275:     },
276:     vertexShader: `varying vec3 vPos; void main(){ vPos = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
277:     fragmentShader: `
278:       uniform vec3 top; uniform vec3 mid; uniform vec3 bottom; varying vec3 vPos;
279:       void main(){
280:         float h = normalize(vPos).y;
281:         vec3 c = mix(bottom, mid, smoothstep(-0.08, 0.2, h));
282:         c = mix(c, top, smoothstep(0.16, 0.85, h));
283:         gl_FragColor = vec4(c, 1.0);
284:       }`,
285:   });
286:   scene.add(new THREE.Mesh(geo, mat));
287: 
288:   const starGeo = new THREE.BufferGeometry();
289:   const arr = [];
290:   for (let i = 0; i < 260; i++) {
291:     const a = Math.random() * TAU;
292:     const y = 0.25 + Math.random() * 0.7;
293:     const r = Math.sqrt(1 - y * y) * 145;
294:     arr.push(Math.cos(a) * r, y * 145, Math.sin(a) * r);
295:   }
296:   starGeo.setAttribute('position', new THREE.Float32BufferAttribute(arr, 3));
297:   const stars = new THREE.Points(
298:     starGeo,
299:     new THREE.PointsMaterial({ color: 0x88a9d0, size: 0.45, transparent: true, opacity: 0.55, depthWrite: false, fog: false })
