310:     emissiveIntensity: 1,
311:   });
312:   const city = new THREE.InstancedMesh(boxGeo, cityMat, 46);
313:   const m = new THREE.Matrix4();
314:   const q = new THREE.Quaternion();
315:   const s = new THREE.Vector3();
