import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const home = process.env.HOME;
const require = createRequire(home + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(home + '/.local/share/omgithub-playwright/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(home + '/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots';
const errors = [];

async function shot(page, name) {
  await page.screenshot({ path: `${OUT}/${name}.jpg`, type: 'jpeg', quality: 80 });
  console.log('SHOT', name);
}
async function state(page, label) {
  const s = await page.evaluate(() => {
    const g = window.NEON.game;
    return {
      state: g.state,
      score: g.score,
      time: +g.timeLeft.toFixed(1),
      owner: g.owner?.name ?? null,
      ownerTeam: g.owner?.team.id ?? null,
      controlled: g.controlled?.name ?? null,
      ball: { x: +g.ball.pos.x.toFixed(1), y: +g.ball.pos.y.toFixed(1), z: +g.ball.pos.z.toFixed(1) },
      charging: g.charging,
      stats: g.stats,
      players: g.players.map(p => ({ n: p.name, t: p.team.id, x: +p.pos.x.toFixed(1), z: +p.pos.z.toFixed(1), st: +p.stamina.toFixed(0) })),
    };
  });
  console.log(label, JSON.stringify(s));
  return s;
}

// ---------- DESKTOP ----------
{
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  const page = await ctx.newPage();
  page.on('pageerror', e => { console.log('PAGEERROR:', e.message); errors.push('desktop:' + e.message); });
  page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE:', m.text()); });
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(1800);
  await shot(page, 'menu-desktop');
  await page.click('#playBtn');
  await page.waitForTimeout(1600);
  await state(page, 'DESKTOP START');
  await shot(page, 'play-desktop');

  // Move forward (toward away goal, +z) with W and sprint
  await page.keyboard.down('KeyW');
  await page.keyboard.down('ShiftLeft');
  await page.waitForTimeout(900);
  await page.keyboard.up('ShiftLeft');
  await page.waitForTimeout(500);
  await page.keyboard.up('KeyW');
  const moved = await state(page, 'AFTER MOVE');
  await shot(page, 'play-desktop-moved');

  // Charged shot: hold space ~0.82s then release
  await page.keyboard.down('Space');
  await page.waitForTimeout(780);
  await shot(page, 'charge-desktop');
  await page.keyboard.up('Space');
  await page.waitForTimeout(650);
  await state(page, 'AFTER SHOT');
  await shot(page, 'shot-desktop');

  // Give ball back to home striker and take a second shot
  await page.evaluate(() => {
    const g = window.NEON.game;
    const p = g.homeTeam.players.find(x => x.role === 'striker');
    p.setPosition(0, 16);
    g.giveBall(p);
  });
  await page.waitForTimeout(200);
  await page.keyboard.down('Space');
  await page.waitForTimeout(820);
  await page.keyboard.up('Space');
  await page.waitForTimeout(1400);
  await state(page, 'SECOND SHOT');
  await shot(page, 'second-shot-desktop');

  // Force a goal via physics to test celebration
  await page.evaluate(() => {
    const g = window.NEON.game;
    g.ball.pos.set(0, 0.8, 26.8);
    g.ball.vel.set(0, 0, 4);
    g.ball.owner = null;
    g.owner = null;
  });
  await page.waitForTimeout(700);
  await state(page, 'GOAL STATE');
  await shot(page, 'goal-desktop');
  await page.waitForTimeout(3000);
  await state(page, 'AFTER KICKOFF RESET');

  // Pause
  await page.keyboard.press('Escape');
  await page.waitForTimeout(400);
  await state(page, 'PAUSED');
  await shot(page, 'pause-desktop');
  await page.click('#resumeBtn');
  await page.waitForTimeout(300);
  await state(page, 'RESUMED');

  // Force end state
  await page.evaluate(() => {
    const g = window.NEON.game;
    g.score.home = 3; g.score.away = 1; g.timeLeft = 0.2;
  });
  await page.waitForTimeout(900);
  await state(page, 'END STATE');
  await shot(page, 'end-desktop');
  await ctx.close();
}

// ---------- MOBILE LANDSCAPE ----------
{
  const ctx = await browser.newContext({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
  const page = await ctx.newPage();
  page.on('pageerror', e => { console.log('PAGEERROR:', e.message); errors.push('landscape:' + e.message); });
  page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE:', m.text()); });
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(1800);
  await shot(page, 'menu-landscape');
  await page.click('#playBtn');
  await page.waitForTimeout(1600);
  await state(page, 'LANDSCAPE START');
  await shot(page, 'play-landscape');

  // touch joystick drag upward
  const box = await page.locator('#stickBase').boundingBox();
  if (box) {
    const cx = box.x + box.width / 2, cy = box.y + box.height / 2;
    await page.mouse.move(cx, cy);
    await page.mouse.down();
    await page.mouse.move(cx, cy - box.height * 0.34, { steps: 6 });
    await page.waitForTimeout(900);
    await state(page, 'LANDSCAPE MOVED');
    await shot(page, 'play-landscape-moved');
    await page.mouse.up();
  }
  // touch shoot hold/release
  const sb = await page.locator('.tbtn-shoot').boundingBox();
  if (sb) {
    const sx = sb.x + sb.width / 2, sy = sb.y + sb.height / 2;
    await page.mouse.move(sx, sy);
    await page.mouse.down();
    await page.waitForTimeout(800);
    await shot(page, 'charge-landscape');
    await page.mouse.up();
    await page.waitForTimeout(900);
    await state(page, 'LANDSCAPE SHOT');
  }
  await ctx.close();
}

await browser.close();
console.log('TOTAL ERRORS', errors.length, errors);

