import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const home = process.env.HOME;
const require = createRequire(home + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(home + '/.local/share/omgithub-playwright/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(home + '/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
page.on('pageerror', e => console.log('PAGEERROR:', e.message));
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1800);
await page.click('#playBtn');
await page.waitForTimeout(1800);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/play-portrait.jpg', type: 'jpeg', quality: 80 });
console.log(await page.evaluate(() => ({ state: window.NEON.game.state, owner: window.NEON.game.owner?.name, cam: window.NEON.camera.position.toArray().map(v=>+v.toFixed(1)), aspect: window.NEON.camera.aspect.toFixed(2), fov: window.NEON.camera.fov.toFixed(1) })));
await browser.close();

