import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const home = process.env.HOME;
const require = createRequire(home + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(home + '/.local/share/omgithub-playwright/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(home + '/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', e => console.log('PAGEERROR:', e.message));
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1500);
await page.click('#playBtn');
await page.waitForTimeout(800);

// --- direct goal flow test ---
console.log('GOAL TEST');
const goalResult = await page.evaluate(() => {
  const g = window.NEON.game;
  const before = { state: g.state, score: { ...g.score } };
  g.scoreGoal('home');
  const after = { state: g.state, score: { ...g.score }, goalTimer: g.goalTimer, pendingEnd: g.pendingEnd, goalTeam: g.goalTeam };
  // advance celebration to completion
  let steps = 0;
  while (g.state === 'goal' && steps < 400) { g.update(1 / 60); steps++; }
  return { before, after, steps, finalState: g.state, finalScore: { ...g.score }, owner: g.owner?.name ?? null, controlled: g.controlled?.name ?? null, ball: g.ball.pos.toArray().map(v => +v.toFixed(1)) };
});
console.log('GOAL', JSON.stringify(goalResult));

// --- AI-only long sim ---
console.log('AI SIM');
const sim = await page.evaluate(() => {
  const g = window.NEON.game;
  g.startMatch('showman', 'pro');
  let goals = 0;
  let lastScore = '0-0';
  const log = [];
  for (let i = 0; i < 60 * 75 && g.state === 'play'; i++) {
    g.update(1 / 60);
    const sc = `${g.score.home}-${g.score.away}`;
    if (sc !== lastScore) { log.push({ t: +(75 - g.timeLeft).toFixed(1), sc, owner: g.owner?.name ?? null }); lastScore = sc; }
  }
  return {
    state: g.state, score: { ...g.score }, time: +g.timeLeft.toFixed(1), stats: g.stats,
    completed: +(75 - g.timeLeft).toFixed(1), log,
    positions: g.players.map(p => ({ n: p.name, t: p.team.id, x: +p.pos.x.toFixed(1), z: +p.pos.z.toFixed(1), st: +p.stamina.toFixed(0) })),
    ball: g.ball.pos.toArray().map(v => +v.toFixed(1)),
  };
});
console.log('SIM', JSON.stringify(sim));
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/ai-sim.jpg', type: 'jpeg', quality: 80 });
await browser.close();

