import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const home = process.env.HOME;
const require = createRequire(home + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(home + '/.local/share/omgithub-playwright/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(home + '/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', e => console.log('PAGEERROR:', e.message));
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1200);
await page.click('#playBtn');
await page.waitForTimeout(500);

const result = await page.evaluate(() => {
  const g = window.NEON.game;
  const trials = [];
  function trial({ x, z, aim, perfect, ratio = 0.82 }) {
    g.resetForKickoff('home');
    const p = g.homeTeam.players.find(q => q.role === 'striker');
    p.setPosition(x, z);
    g.giveBall(p);
    g.kickoffTimer = 0;
    // park defenders out of the lane
    for (const q of g.awayTeam.players) q.setPosition(q.pos.x, FIELD_HALF() - 3);
    const before = g.score.home;
    g.shoot(p, ratio, perfect, false, { x: aim, y: 0 });
    let frames = 0;
    let state = '';
    while (frames < 180) {
      g.update(1 / 60);
      state = g.state;
      if (state === 'goal' || g.score.home > before) break;
      frames++;
    }
    const out = { x, z, aim, perfect, ratio, scored: g.score.home > before, state, frames, keeperX: +g.awayTeam.keeper.pos.x.toFixed(2), keeperDive: g.awayTeam.keeper.dive.active, ball: g.ball.pos.toArray().map(v => +v.toFixed(2)), saves: g.stats.saves || 0 };
    if (g.state === 'goal') { g.goalTimer = 0.001; g.update(1 / 60); }
    return out;
  }
  function FIELD_HALF() { return 27; }
  const cases = [];
  for (const z of [10, 14, 17]) {
    for (const aim of [1, -1, 0]) {
      for (const perfect of [true, false]) {
        cases.push({ x: 0, z, aim, perfect });
      }
    }
  }
  // also from wide
  cases.push({ x: -6, z: 13, aim: 1, perfect: true });
  cases.push({ x: 6, z: 13, aim: -1, perfect: true });
  for (const c of cases) trials.push(trial(c));
  return trials;
});
console.log(JSON.stringify(result, null, 1));
await browser.close();

