import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const home = process.env.HOME;
const require = createRequire(home + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(home + '/.local/share/omgithub-playwright/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(home + '/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots';
const errors = [];

async function advance(page, seconds) {
  await page.evaluate((s) => {
    const g = window.NEON.game;
    let n = Math.min(1200, Math.max(1, Math.round(s * 60)));
    while (n-- > 0) {
      g.update(1 / 60);
      window.NEON.input?.endFrame?.();
    }
  }, seconds);
  await page.waitForTimeout(120);
}

async function shot(page, name) {
  await page.screenshot({ path: `${OUT}/${name}.jpg`, type: 'jpeg', quality: 80 });
}

function watch(page) {
  page.on('pageerror', e => { console.log('PAGEERROR:', e.message); errors.push(e.message); });
  page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE:', m.text()); });
}

// desktop
{
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  watch(page);
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(900);
  await shot(page, 'final-menu-desktop');
  await page.click('#playBtn');
  await advance(page, 1.15);
  await shot(page, 'final-play-desktop');
  await page.keyboard.down('Space');
  await page.waitForTimeout(700);
  await shot(page, 'final-charge-desktop');
  console.log('desktop charge', await page.evaluate(() => ({ charging: window.NEON.game.charging, ratio: +(window.NEON.game.chargeTime / 0.95).toFixed(2), meter: document.getElementById('chargeMeter').className, fill: document.getElementById('chargeFill').style.width })));
  await page.keyboard.up('Space');
  await page.waitForTimeout(250);
  await page.evaluate(() => { window.NEON.game.scoreGoal('home'); });
  await advance(page, 0.75);
  await shot(page, 'final-goal-desktop');
  console.log('goal overlay', await page.evaluate(() => ({ state: window.NEON.game.state, score: window.NEON.game.score, goal: !document.getElementById('goalFlash').classList.contains('is-hidden'), cam: window.NEON.camera.position.toArray().map(v => +v.toFixed(1)) })));
  await advance(page, 3.1);
  await shot(page, 'final-kickoff-desktop');
  console.log('kickoff', await page.evaluate(() => ({ state: window.NEON.game.state })));
  await page.keyboard.press('Escape');
  await advance(page, 0.2);
  await shot(page, 'final-pause-desktop');
  console.log('pause', await page.evaluate(() => ({ state: window.NEON.game.state, visible: !document.getElementById('pause').classList.contains('is-hidden') })));
  if (await page.locator('#resumeBtn').isVisible()) {
    await page.click('#resumeBtn');
    await advance(page, 0.3);
  }
  await page.evaluate(() => { const g = window.NEON.game; g.score.home = 4; g.score.away = 2; g.timeLeft = 0.15; g.state = 'play'; });
  await advance(page, 0.9);
  await shot(page, 'final-end-desktop');
  console.log('end', await page.evaluate(() => ({ state: window.NEON.game.state, title: document.getElementById('endTitle').textContent, score: document.getElementById('endScore').textContent })));
  await page.close();
}

// portrait
{
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
  watch(page);
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(900);
  await shot(page, 'final-menu-portrait');
