  await shot(page, 'final-play-portrait');
  console.log('portrait state', await page.evaluate(() => ({ state: window.NEON.game.state, owner: window.NEON.game.owner?.name ?? null, cam: window.NEON.camera.position.toArray().map(v => +v.toFixed(1)), ball: window.NEON.game.ball.pos.toArray().map(v => +v.toFixed(1)) })));
  const sb = await page.locator('.tbtn-shoot').boundingBox();
  if (sb) {
    await page.mouse.move(sb.x + sb.width / 2, sb.y + sb.height / 2);
    await page.mouse.down();
    await page.waitForTimeout(560);
    await shot(page, 'final-charge-portrait');
    await page.mouse.up();
    await advance(page, 0.5);
  }
  console.log('portrait after shot', await page.evaluate(() => ({ state: window.NEON.game.state, shots: window.NEON.game.stats.shots, meter: document.getElementById('chargeMeter').className })));
  await page.close();
}

// landscape
{
  const page = await browser.newPage({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
  watch(page);
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(900);
  await shot(page, 'final-menu-landscape');
  await page.click('#playBtn');
  await advance(page, 1.2);
  await shot(page, 'final-play-landscape');
  console.log('landscape state', await page.evaluate(() => ({ state: window.NEON.game.state, owner: window.NEON.game.owner?.name ?? null, cam: window.NEON.camera.position.toArray().map(v => +v.toFixed(1)) })));
  await page.close();
}

// tablet
{
  const page = await browser.newPage({ viewport: { width: 820, height: 1180 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
  watch(page);
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(900);
  await shot(page, 'final-menu-tablet');
  await page.close();
}

await browser.close();
console.log('ERRORS', errors.length);

