import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const home = process.env.HOME;
const require = createRequire(home + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(home + '/.local/share/omgithub-playwright/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(home + '/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', e => { console.log('PAGEERROR:', e.message); errors.push(e.message); });
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE:', m.text()); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(800);
await page.click('#playBtn');
await page.waitForTimeout(400);
const setup = await page.evaluate(() => {
  const g = window.NEON.game;
  const p = g.controlled || g.homeTeam.players.find(q => q.role === 'striker');
  let i = 0;
  for (const q of g.awayTeam.players) q.setPosition((i++ % 2 ? -1 : 1) * 14, 22);
  for (const q of g.homeTeam.players) { if (q !== p) q.setPosition((i++ % 2 ? -1 : 1) * 14, -18); }
  p.setPosition(0, 8);
  g.giveBall(p);
  g.controlLock = 0;
  g.kickoffTimer = 0;
  return { state: g.state, owner: g.owner?.name, controlled: g.controlled?.name, shots: g.stats.shots };
});
console.log('setup', setup);
await page.keyboard.down('Space');
await page.waitForTimeout(650);
console.log('holding', await page.evaluate(() => ({
  charging: window.NEON.game.charging,
  ratio: +(window.NEON.game.chargeTime / 0.95).toFixed(2),
  meter: document.getElementById('chargeMeter').className,
  fill: document.getElementById('chargeFill').style.width,
  perfect: document.getElementById('chargeMeter').classList.contains('is-perfect'),
  shootBtn: document.querySelector('.tbtn-shoot')?.className ?? null,
})));
await page.screenshot({ path: '/tmp/opencode/charge-check.jpg', type: 'jpeg', quality: 82 });
await page.keyboard.up('Space');
await page.waitForTimeout(150);
console.log('released', await page.evaluate(() => ({
  charging: window.NEON.game.charging,
  meter: document.getElementById('chargeMeter').className,
  fill: document.getElementById('chargeFill').style.width,
  shots: window.NEON.game.stats.shots,
  shootBtn: document.querySelector('.tbtn-shoot')?.className ?? null,
})));
await page.waitForTimeout(500);
console.log('after shot', await page.evaluate(() => ({
  state: window.NEON.game.state,
  owner: window.NEON.game.owner?.name ?? null,
  score: { ...window.NEON.game.score },
  saves: window.NEON.game.stats.saves || 0,
  ball: window.NEON.game.ball.pos.toArray().map(v => +v.toFixed(1)),
})));

// Goal camera sample at two points in the celebration
await page.evaluate(() => {
  const g = window.NEON.game;
  g.ball.reset(2, 26);
  g.lastTouch = g.homeTeam.players.find(p => p.role === 'striker');
  g.state = 'play';
  g.scoreGoal('home');
});
await page.waitForTimeout(900);
console.log('goal 0.9s', await page.evaluate(() => ({ state: window.NEON.game.state, cam: window.NEON.camera.position.toArray().map(v => +v.toFixed(1)) })));
await page.screenshot({ path: '/tmp/opencode/goal-09.jpg', type: 'jpeg', quality: 82 });
await page.waitForTimeout(1000);
console.log('goal 1.9s', await page.evaluate(() => ({ state: window.NEON.game.state, cam: window.NEON.camera.position.toArray().map(v => +v.toFixed(1)), confetti: window.NEON.game.effects.confettiPieces?.length ?? null })));
await page.screenshot({ path: '/tmp/opencode/goal-19.jpg', type: 'jpeg', quality: 82 });

// Pause after forced kickoff to make sure the overlay opens from play.
await page.evaluate(() => { const g = window.NEON.game; g.goalTimer = 0.01; g.update(0.02); });
await page.waitForTimeout(300);
await page.keyboard.press('Escape');
await page.waitForTimeout(250);
console.log('pause', await page.evaluate(() => ({ state: window.NEON.game.state, visible: !document.getElementById('pause').classList.contains('is-hidden') })));
await page.click('#resumeBtn');
await page.waitForTimeout(250);
console.log('resume', await page.evaluate(() => window.NEON.game.state));
console.log('ERRORS', errors.length);
await browser.close();

