cat > /tmp/opencode/sim.mjs <<'EOF'
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const home = process.env.HOME;
const require = createRequire(home + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(home + '/.local/share/omgithub-playwright/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(home + '/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', e => console.log('PAGEERROR:', e.message));
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(700);
await page.click('#playBtn');
await page.waitForTimeout(300);
const out = await page.evaluate(() => {
  const g = window.NEON.game;
  let goals = [];
  let last = `${g.score.home}-${g.score.away}`;
  let maxBall = 0, bad = 0;
  for (let i = 0; i < 60 * 90; i++) {
    g.update(1 / 60);
    g.input.endFrame();
    const s = `${g.score.home}-${g.score.away}`;
    if (s !== last) { goals.push({ at: +(i / 60).toFixed(1), score: s, team: g.goalTeam }); last = s; }
    maxBall = Math.max(maxBall, Math.abs(g.ball.pos.x), Math.abs(g.ball.pos.z));
    if (!Number.isFinite(g.ball.pos.x + g.ball.pos.y + g.ball.pos.z)) bad++;
  }
  return { state: g.state, score: g.score, timeLeft: +g.timeLeft.toFixed(1), goals, shots: g.stats.shots, saves: g.stats.saves || 0, tackles: g.stats.tackles, maxBall: +maxBall.toFixed(1), bad, owner: g.owner?.name ?? null, possession: g.possessionTime };
});
console.log(out);
await browser.close();
EOF
